#!/usr/bin/env python3
# Raw echo server: logs raw request bytes to a file, responds with configurable response.
import socket, sys, threading, os, time

PORT = int(sys.argv[1]) if len(sys.argv) > 1 else 8099
LOG = sys.argv[2] if len(sys.argv) > 2 else '/tmp/srv/last_request.bin'
RESP_FILE = sys.argv[3] if len(sys.argv) > 3 else '/tmp/srv/response.bin'

def handle(conn):
    conn.settimeout(2.0)
    data = b''
    try:
        while True:
            chunk = conn.recv(65536)
            if not chunk:
                break
            data += chunk
            # crude: check if headers complete and content-length satisfied
            if b'\r\n\r\n' in data:
                head, _, body = data.partition(b'\r\n\r\n')
                cl = 0
                chunked = False
                for line in head.split(b'\r\n')[1:]:
                    k, _, v = line.partition(b':')
                    if k.strip().lower() == b'content-length':
                        cl = int(v.strip())
                    if k.strip().lower() == b'transfer-encoding' and b'chunked' in v.lower():
                        chunked = True
                if chunked:
                    if body.endswith(b'0\r\n\r\n'):
                        break
                elif len(body) >= cl:
                    break
    except socket.timeout:
        pass
    with open(LOG, 'wb') as f:
        f.write(data)
    try:
        with open(RESP_FILE, 'rb') as f:
            resp = f.read()
    except FileNotFoundError:
        resp = b'HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 13\r\n\r\n{"ok": true}\n'
    conn.sendall(resp)
    time.sleep(0.05)
    conn.close()

s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
s.bind(('127.0.0.1', PORT))
s.listen(5)
while True:
    c, _ = s.accept()
    threading.Thread(target=handle, args=(c,), daemon=True).start()
