//! An insertion ordered multimap for HTTP headers.
//!
//! The observable semantics mirror those of a classic hash-map-with-entries
//! design: inserting a new name appends an entry, inserting an existing name
//! replaces its values in place, appending adds a value to the existing entry
//! and removing an entry swaps the last entry into the removed slot.

use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct HeaderName(String);

impl HeaderName {
    /// Validate and normalize (lowercase) a header name.
    pub fn new(name: &str) -> Result<HeaderName, InvalidHeaderName> {
        if name.is_empty() || !name.bytes().all(is_token_char) {
            return Err(InvalidHeaderName);
        }
        Ok(HeaderName(name.to_ascii_lowercase()))
    }

    /// Create a header name from a string known to be valid.
    pub fn from_static(name: &str) -> HeaderName {
        HeaderName::new(name).expect("static header name must be valid")
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }

    /// Title-cased representation used for display and on the wire.
    pub fn titled(&self) -> String {
        titlecase_header(&self.0)
    }
}

impl fmt::Display for HeaderName {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InvalidHeaderName;

impl fmt::Display for InvalidHeaderName {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("invalid HTTP header name")
    }
}

impl std::error::Error for InvalidHeaderName {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InvalidHeaderValue;

impl fmt::Display for InvalidHeaderValue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("failed to parse header value")
    }
}

impl std::error::Error for InvalidHeaderValue {}

fn is_token_char(b: u8) -> bool {
    b.is_ascii_alphanumeric()
        || matches!(
            b,
            b'!' | b'#' | b'$' | b'%' | b'&' | b'\'' | b'*' | b'+' | b'-' | b'.' | b'^' | b'_' | b'`' | b'|' | b'~'
        )
}

/// Validate a header value: no control characters except horizontal tab.
pub fn validate_header_value(value: &[u8]) -> Result<(), InvalidHeaderValue> {
    for &b in value {
        if b < 32 && b != b'\t' || b == 127 {
            return Err(InvalidHeaderValue);
        }
    }
    Ok(())
}

pub fn titlecase_header(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    let mut upper = true;
    for c in name.chars() {
        if upper {
            out.extend(c.to_uppercase());
        } else {
            out.extend(c.to_lowercase());
        }
        upper = c == '-';
    }
    out
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct HeaderMap {
    entries: Vec<(HeaderName, Vec<Vec<u8>>)>,
}

impl HeaderMap {
    pub fn new() -> HeaderMap {
        HeaderMap::default()
    }

    fn position(&self, name: &str) -> Option<usize> {
        self.entries.iter().position(|(n, _)| n.as_str() == name)
    }

    pub fn contains_key(&self, name: &str) -> bool {
        self.position(name).is_some()
    }

    pub fn get(&self, name: &str) -> Option<&[u8]> {
        self.position(name)
            .map(|i| self.entries[i].1[0].as_slice())
    }

    pub fn get_str(&self, name: &str) -> Option<&str> {
        self.get(name).and_then(|v| std::str::from_utf8(v).ok())
    }

    pub fn get_all(&self, name: &str) -> Vec<&[u8]> {
        match self.position(name) {
            Some(i) => self.entries[i].1.iter().map(|v| v.as_slice()).collect(),
            None => Vec::new(),
        }
    }

    /// Insert a header, replacing any existing values for the same name.
    pub fn insert(&mut self, name: HeaderName, value: impl Into<Vec<u8>>) {
        let value = value.into();
        match self.position(name.as_str()) {
            Some(i) => self.entries[i].1 = vec![value],
            None => self.entries.push((name, vec![value])),
        }
    }

    /// Append a header value, keeping any existing values for the same name.
    pub fn append(&mut self, name: HeaderName, value: impl Into<Vec<u8>>) {
        let value = value.into();
        match self.position(name.as_str()) {
            Some(i) => self.entries[i].1.push(value),
            None => self.entries.push((name, vec![value])),
        }
    }

    /// Insert the header only if it is not present yet.
    pub fn insert_if_absent(&mut self, name: HeaderName, value: impl Into<Vec<u8>>) {
        if !self.contains_key(name.as_str()) {
            self.insert(name, value);
        }
    }

    /// Remove all values for the given header name.
    pub fn remove(&mut self, name: &str) -> Option<Vec<Vec<u8>>> {
        let i = self.position(name)?;
        let (_, values) = self.entries.swap_remove(i);
        Some(values)
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn len(&self) -> usize {
        self.entries.iter().map(|(_, v)| v.len()).sum()
    }

    /// Iterate over all (name, value) pairs in map order.
    pub fn iter(&self) -> impl Iterator<Item = (&HeaderName, &[u8])> {
        self.entries
            .iter()
            .flat_map(|(n, vs)| vs.iter().map(move |v| (n, v.as_slice())))
    }

    pub fn names(&self) -> impl Iterator<Item = &HeaderName> {
        self.entries.iter().map(|(n, _)| n)
    }

    /// Merge another map into this one (insert for the first value of each
    /// name, append for the following ones).
    pub fn extend(&mut self, other: &HeaderMap) {
        for (name, values) in &other.entries {
            for (i, value) in values.iter().enumerate() {
                if i == 0 {
                    self.insert(name.clone(), value.clone());
                } else {
                    self.append(name.clone(), value.clone());
                }
            }
        }
    }
}
