//! HTTPie-style nested JSON paths, e.g. `a[b][0]=value`.

use std::fmt;

use serde_json::Value;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TokenKind {
    Text,
    Number,
    LeftBracket,
    RightBracket,
}

impl TokenKind {
    fn name(self) -> &'static str {
        match self {
            TokenKind::Text => "text",
            TokenKind::Number => "number",
            TokenKind::LeftBracket => "'['",
            TokenKind::RightBracket => "']'",
        }
    }
}

#[derive(Debug, Clone)]
struct Token {
    kind: TokenKind,
    value: String,
    start: usize,
    end: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum PathKind {
    Key(String),
    Index(usize),
    Append,
}

impl PathKind {
    fn name(&self) -> &'static str {
        match self {
            PathKind::Key(_) => "key",
            PathKind::Index(_) => "index",
            PathKind::Append => "append",
        }
    }
}

#[derive(Debug, Clone)]
struct Path {
    kind: PathKind,
    start: usize,
    end: usize,
}

/// A syntax or type error with a pointer into the offending source.
#[derive(Debug, Clone)]
pub struct NestedJsonError {
    message: String,
    source: String,
    start: usize,
    end: usize,
}

impl fmt::Display for NestedJsonError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut source: String = self.source.chars().collect();
        let len = source.chars().count();
        if len < self.end {
            source.extend(std::iter::repeat(' ').take(self.end - len));
        }
        write!(f, "{}\n\n  {}\n  ", self.message, source)?;
        for _ in 0..self.start {
            f.write_str(" ")?;
        }
        for _ in self.start..self.end.max(self.start + 1) {
            f.write_str("^")?;
        }
        Ok(())
    }
}

impl std::error::Error for NestedJsonError {}

fn tokenize(source: &str) -> Vec<Token> {
    let chars: Vec<char> = source.chars().collect();
    let mut tokens = Vec::new();
    let mut buffer = String::new();
    let mut buffer_len = 0usize;
    let mut backslashes = 0usize;
    let mut cursor = 0usize;

    fn flush(
        tokens: &mut Vec<Token>,
        buffer: &mut String,
        buffer_len: &mut usize,
        backslashes: &mut usize,
        cursor: usize,
    ) {
        if buffer.is_empty() {
            return;
        }
        let value = std::mem::take(buffer);
        let is_number = *backslashes == 0 && value.bytes().all(|b| b.is_ascii_digit());
        let kind = if is_number { TokenKind::Number } else { TokenKind::Text };
