            kind,
            value,
            start: cursor - (*buffer_len + *backslashes),
            end: cursor,
        });
        *buffer_len = 0;
        *backslashes = 0;
    }

    while cursor < chars.len() {
        let c = chars[cursor];
        match c {
            '[' | ']' => {
                flush(&mut tokens, &mut buffer, &mut buffer_len, &mut backslashes, cursor);
                let kind = if c == '[' { TokenKind::LeftBracket } else { TokenKind::RightBracket };
                tokens.push(Token { kind, value: c.to_string(), start: cursor, end: cursor + 1 });
