                    buffer_len += 1;
                }
                buffer.push(next);
                buffer_len += 1;
                cursor += 1;
            }
            _ => {
                buffer.push(c);
                buffer_len += 1;
            }
        }
        cursor += 1;
    }
    flush(&mut tokens, &mut buffer, &mut buffer_len, &mut backslashes, cursor);
    tokens
