            message: format!("expected {}", suffix),
            source: self.source.to_string(),
            start,
            end,
        })
    }

    fn parse(mut self) -> Result<Vec<Path>, NestedJsonError> {
        let mut paths = Vec::new();

        // root: text | '[' number ']' | '[' ']'
        let token = self.expect(&[TokenKind::Text, TokenKind::LeftBracket])?;
        match token.kind {
            TokenKind::Text | TokenKind::Number => {
                paths.push(Path { kind: PathKind::Key(token.value), start: token.start, end: token.end });
