            _ => {
                let inner = self.expect(&[TokenKind::Number, TokenKind::RightBracket])?;
                if inner.kind == TokenKind::Number {
                    let close = self.expect(&[TokenKind::RightBracket])?;
                    paths.push(Path {
                        kind: PathKind::Index(parse_index(&inner.value)),
                        start: token.start,
                        end: close.end,
                    });
                } else {
                    paths.push(Path { kind: PathKind::Append, start: token.start, end: inner.end });
                }
            }
        }

        while self.can_advance() {
            let open = self.expect(&[TokenKind::LeftBracket])?;
            let token = self.expect(&[TokenKind::Text, TokenKind::Number, TokenKind::RightBracket])?;
            match token.kind {
                TokenKind::RightBracket => {
                    paths.push(Path { kind: PathKind::Append, start: open.start, end: token.end });
                }
                TokenKind::Text => {
                    let close = self.expect(&[TokenKind::RightBracket])?;
                    paths.push(Path { kind: PathKind::Key(token.value), start: open.start, end: close.end });
