                        start: open.start,
                        end: close.end,
                    });
                }
                TokenKind::LeftBracket => unreachable!(),
            }
        }
        Ok(paths)
    }
}

fn parse_index(digits: &str) -> usize {
    digits.parse().unwrap_or(usize::MAX)
}

fn parse(source: &str) -> Result<Vec<Path>, NestedJsonError> {
    let mut tokens = tokenize(source);
    // A root token consisting only of digits is still a key.
    if let Some(first) = tokens.first_mut() {
