fn type_name(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "bool",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

fn empty_for(kind: &PathKind) -> Value {
    match kind {
        PathKind::Key(_) => Value::Object(Default::default()),
        PathKind::Index(_) | PathKind::Append => Value::Array(Vec::new()),
    }
}

/// Insert `value` into `root` at the nested path described by `key`.
pub fn insert(root: &mut Option<Value>, key: &str, value: Value) -> Result<(), NestedJsonError> {
    let paths = parse(key)?;
    if root.is_none() {
        *root = Some(empty_for(&paths[0].kind));
    }
    let mut cursor = root.as_mut().unwrap();
    let last = paths.len() - 1;
    for (index, path) in paths.iter().enumerate() {
        let is_last = index == last;
        let type_error = |cursor: &Value, expected: &str| NestedJsonError {
            message: format!(
                "Can't perform '{}' based access on '{}' which has a type of '{}' but this operation requires a type of '{}'.",
                path.kind.name(),
                key.chars().take(path.start).collect::<String>(),
                type_name(cursor),
                expected
