            PathKind::Key(name) => {
                if !cursor.is_object() {
                    return Err(type_error(cursor, "object"));
                }
                let map = cursor.as_object_mut().unwrap();
                if is_last {
                    map.insert(name.clone(), value);
                    return Ok(());
                }
                let next_kind = &paths[index + 1].kind;
                if !map.contains_key(name) {
                    map.insert(name.clone(), empty_for(next_kind));
                }
                cursor = map.get_mut(name).unwrap();
            }
            PathKind::Index(i) => {
                if !cursor.is_array() {
                    return Err(type_error(cursor, "array"));
                }
                let arr = cursor.as_array_mut().unwrap();
                let i = *i;
                while arr.len() <= i {
                    arr.push(Value::Null);
                }
                if is_last {
                    arr[i] = value;
                    return Ok(());
                }
                cursor = &mut arr[i];
            }
            PathKind::Append => {
                if !cursor.is_array() {
                    return Err(type_error(cursor, "array"));
                }
                let arr = cursor.as_array_mut().unwrap();
                if is_last {
                    arr.push(value);
                    return Ok(());
                }
                let next_kind = &paths[index + 1].kind;
                arr.push(empty_for(next_kind));
                cursor = arr.last_mut().unwrap();
            }
        }
    }
    Ok(())
}
