        RequestItems { items, body_from_file: None }
    }

    /// Headers specified on the command line, and those to be removed.
    pub fn headers(&self) -> Result<(HeaderMap, Vec<HeaderName>)> {
        let mut headers = HeaderMap::new();
        let mut to_unset: Vec<HeaderName> = Vec::new();
        for item in &self.items {
            match item {
                RequestItem::HttpHeader(key, value) => {
                    let name = HeaderName::new(key)?;
                    let value = read_value(value)?;
                    crate::headers::validate_header_value(value.as_bytes())?;
                    headers.append(name.clone(), value.into_bytes());
                    to_unset.retain(|n| n != &name);
                }
                RequestItem::HttpHeaderToUnset(key) => {
                    let name = HeaderName::new(key)?;
                    headers.remove(name.as_str());
                    if !to_unset.contains(&name) {
                        to_unset.push(name);
                    }
                }
                _ => {}
            }
        }
        Ok((headers, to_unset))
    }

    pub fn query(&self) -> Result<Vec<(String, String)>> {
        let mut query = Vec::new();
        for item in &self.items {
            if let RequestItem::UrlParam(key, value) = item {
                query.push((key.clone(), read_value(value)?));
            }
        }
        Ok(query)
    }

    pub fn has_form_files(&self) -> bool {
        self.items.iter().any(|i| matches!(i, RequestItem::FormFile { .. }))
    }

    pub fn is_multipart(&self, body_type: BodyType) -> bool {
        body_type == BodyType::Multipart || (body_type == BodyType::Form && self.has_form_files())
