                        }
                        RequestItem::FormFile { .. } => {
                            return Err(anyhow!("Can't use file fields in JSON mode (perhaps you meant --form?)"));
                        }
                        _ => {}
                    }
                }
                Ok(Body::Json(root))
            }
            BodyType::Form if !self.has_form_files() => {
                let mut fields = Vec::new();
                for item in &self.items {
