                        }
                        _ => {}
                    }
                }
                Ok(Body::Multipart { text_fields, files })
            }
        }
    }

    pub fn has_data(&self) -> bool {
        self.items.iter().any(|i| {
            matches!(
                i,
                RequestItem::DataField { .. } | RequestItem::JsonField(..) | RequestItem::FormFile { .. }
