pub enum RequestItem {
    /// `name:value` (`value` may be empty with the `;` separator)
    HttpHeader(String, String),
    /// `name:`
    HttpHeaderToUnset(String),
    /// `key==value`
    UrlParam(String, String),
    /// `key=value`
    DataField { key: String, value: String },
    /// `key:=value`
    JsonField(String, Value),
    /// `key@filename[;type=..][;filename=..]`
    FormFile {
        key: String,
        file_name: String,
        file_type: Option<String>,
        file_name_header: Option<String>,
    },
}

/// Error for a request item that could not be parsed.
#[derive(Debug)]
pub struct InvalidRequestItem {
    pub item: String,
    pub detail: Option<String>,
}

impl fmt::Display for InvalidRequestItem {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Invalid value for '[REQUEST_ITEM]...': {:?}", self.item)?;
        if let Some(detail) = &self.detail {
            write!(f, " {}", detail)?;
        }
        Ok(())
    }
}

impl std::error::Error for InvalidRequestItem {}

const SEPARATORS: &[&str] = &["==", ":=", "=", "@", ":", ";"];
const SPECIAL_CHARS: &str = "=@:;\\";

/// Unescape backslash sequences for the separator characters.
fn unescape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.peek() {
                Some(&n) if SPECIAL_CHARS.contains(n) => {
                    out.push(n);
                    chars.next();
                }
                _ => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// Split the item at the first unescaped separator.
fn split(item: &str) -> Option<(String, &'static str, String)> {
    let mut key = String::new();
    let mut i = 0;
    let bytes = item.as_bytes();
    while i < item.len() {
        let rest = &item[i..];
        let c = rest.chars().next().unwrap();
        if c == '\\' {
            let mut it = rest.chars();
            it.next();
            match it.next() {
                Some(n) if SPECIAL_CHARS.contains(n) => {
                    key.push(n);
                    i += 1 + n.len_utf8();
                    continue;
                }
                _ => {
                    key.push('\\');
                    i += 1;
                    continue;
                }
            }
        }
        for sep in SEPARATORS {
            if rest.starts_with(sep) {
                let value = unescape(&item[i + sep.len()..]);
                return Some((key, sep, value));
            }
        }
        let _ = bytes;
        key.push(c);
        i += c.len_utf8();
    }
    None
}

impl RequestItem {
    pub fn parse(item: &str) -> Result<RequestItem, InvalidRequestItem> {
        let (key, sep, value) = split(item).ok_or_else(|| InvalidRequestItem {
            item: item.to_string(),
            detail: None,
        })?;
        match sep {
            "==" => Ok(RequestItem::UrlParam(key, value)),
            ":=" => {
                if let Some(file) = value.strip_prefix('@') {
                    // Deferred until the body is built so that the file is read
                    // only when needed.
                    return Ok(RequestItem::JsonField(key, Value::String(format!("\u{0}@{}", file))));
                }
                let json: Value = serde_json::from_str(&value).map_err(|e| InvalidRequestItem {
                    item: item.to_string(),
                    detail: Some(e.to_string()),
                })?;
                Ok(RequestItem::JsonField(key, json))
            }
            "=" => Ok(RequestItem::DataField { key, value }),
            "@" => {
                let mut parts = value.split(';');
                let file_name = parts.next().unwrap_or("").to_string();
                let mut file_type = None;
                let mut file_name_header = None;
                for part in parts {
                    if let Some(t) = part.strip_prefix("type=") {
                        file_type = Some(t.to_string());
                    } else if let Some(n) = part.strip_prefix("filename=") {
                        file_name_header = Some(n.to_string());
                    }
                }
                Ok(RequestItem::FormFile { key, file_name, file_type, file_name_header })
            }
            ":" => {
                if value.is_empty() {
                    Ok(RequestItem::HttpHeaderToUnset(key))
                } else {
                    Ok(RequestItem::HttpHeader(key, value))
                }
            }
            ";" => {
                if value.is_empty() {
                    Ok(RequestItem::HttpHeader(key, value))
                } else {
                    Err(InvalidRequestItem { item: item.to_string(), detail: None })
                }
            }
            _ => unreachable!(),
        }
    }
}

/// Read a value that may refer to a file (`@path`).
fn read_value(value: &str) -> Result<String> {
    if let Some(path) = value.strip_prefix('@') {
        let bytes = fs::read(path)?;
        Ok(String::from_utf8_lossy(&bytes).into_owned())
    } else {
        Ok(value.to_string())
    }
}

