/// Produce a clap style error (`error: ...` followed by the usage).
fn clap_error(cmd: &mut clap::Command, kind: ErrorKind, message: impl fmt::Display) -> anyhow::Error {
    let err = cmd.error(kind, message);
    anyhow::Error::new(ExitError { message: err.render().to_string(), code: err.exit_code() })
}

fn parse_format_options(cmd: &mut clap::Command, s: &str) -> Result<FormatOptions> {
    let mut opts = FormatOptions::default();
    for part in s.split(',') {
        let (key, value) = match part.split_once(':') {
            Some(kv) => kv,
            None => {
                return Err(clap_error(
                    cmd,
                    ErrorKind::ValueValidation,
                    format!("invalid value '{}' for '--format-options <FORMAT_OPTIONS>': Invalid format option: {}", s, part),
                ))
            }
        };
        match key {
            "json.indent" => {
                opts.json_indent = Some(value.parse().map_err(|_| {
                    clap_error(
                        cmd,
                        ErrorKind::ValueValidation,
                        format!("invalid value '{}' for '--format-options <FORMAT_OPTIONS>': Invalid value for json.indent: {}", s, value),
                    )
                })?)
            }
            "json.format" => opts.json_format = Some(parse_bool(cmd, s, key, value)?),
            "headers.sort" => opts.headers_sort = Some(parse_bool(cmd, s, key, value)?),
            _ => {
                return Err(clap_error(
                    cmd,
                    ErrorKind::ValueValidation,
                    format!("invalid value '{}' for '--format-options <FORMAT_OPTIONS>': Unknown format option: {}", s, key),
                ))
            }
        }
    }
    Ok(opts)
}

fn parse_bool(cmd: &mut clap::Command, whole: &str, key: &str, value: &str) -> Result<bool> {
    match value {
        "true" => Ok(true),
        "false" => Ok(false),
        _ => Err(clap_error(
            cmd,
            ErrorKind::ValueValidation,
            format!("invalid value '{}' for '--format-options <FORMAT_OPTIONS>': Invalid value for {}: {}", whole, key, value),
        )),
    }
}

/// Default scheme for the invoked binary name.
