pub fn parse(bin_name: &str, matches: &ArgMatches) -> Result<Parsed> {
    let mut cmd = cli::build_command().bin_name(bin_name.to_string());
    let s = |name: &str| matches.get_one::<String>(name).cloned();
    let flag = |name: &str| matches.get_flag(name);
    let count = |name: &str| matches.get_count(name);

    if let Some(kind) = s("generate") {
        let generate = match kind.as_str() {
            "complete-bash" => Generate::CompleteBash,
            "complete-elvish" => Generate::CompleteElvish,
            "complete-fish" => Generate::CompleteFish,
            "complete-nushell" => Generate::CompleteNushell,
            "complete-powershell" => Generate::CompletePowershell,
            "complete-zsh" => Generate::CompleteZsh,
            _ => Generate::Man,
        };
        return Ok(Parsed::Generate(generate));
    }

    let raw_method_or_url = s("raw_method_or_url");
    let raw_rest_args: Vec<String> = matches
        .get_many::<String>("raw_rest_args")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    if raw_method_or_url.as_deref() == Some("help") {
        return Ok(Parsed::LongHelp);
    }

    let httpie_compat_mode =
        matches!(bin_name, "http" | "https") || std::env::var_os("XH_HTTPIE_COMPAT_MODE").is_some();

    // Method and URL detection
    let first = raw_method_or_url.clone().unwrap_or_default();
    let (method, url_arg, rest): (Option<String>, String, Vec<String>) =
        if !first.is_empty() && first.chars().all(|c| c.is_ascii_alphabetic()) {
            let mut rest = raw_rest_args.clone();
            if rest.is_empty() {
                return Err(clap_error(&mut cmd, ErrorKind::MissingRequiredArgument, "Missing <URL>"));
            }
            let url = rest.remove(0);
            (Some(first.to_ascii_uppercase()), url, rest)
        } else {
            (None, first, raw_rest_args.clone())
        };

    let mut items = Vec::new();
    for item in &rest {
        match RequestItem::parse(item) {
            Ok(item) => items.push(item),
            Err(e) => return Err(clap_error(&mut cmd, ErrorKind::InvalidValue, e)),
        }
    }
    let request_items = RequestItems::new(items);

    let https = flag("https");
    let default_scheme = if https { Some("https".to_string()) } else { s("default_scheme") };
    let scheme = default_scheme.clone().unwrap_or_else(|| default_scheme_for(bin_name).to_string());

    let query = request_items.query()?;
    let url = match crate::url::construct_url(&url_arg, &scheme, &query) {
        Ok(url) => url,
        Err(e) => {
            return Err(clap_error(&mut cmd, ErrorKind::InvalidValue, format!("Invalid <URL>: {}", e)))
        }
    };

    let raw = s("raw");
    if raw.is_some() && (request_items.has_data() || request_items.body_from_file.is_some()) {
        let mut fresh = cli::build_command();
        return Err(clap_error(
            &mut fresh,
            ErrorKind::ArgumentConflict,
            "Request body (from --raw) and request data (key=value) cannot be mixed.",
        ));
    }

    let pretty = s("pretty").map(|p| match p.as_str() {
        "all" => Pretty::All,
        "colors" => Pretty::Colors,
        "format" => Pretty::Format,
        _ => Pretty::None,
    });
    let mut format_options = Vec::new();
    if let Some(values) = matches.get_many::<String>("format_options") {
        for v in values {
            format_options.push(parse_format_options(&mut cmd, v)?);
        }
    }
    let style = s("style").map(|t| match t.as_str() {
        "auto" => Theme::Auto,
        "solarized" => Theme::Solarized,
        "monokai" => Theme::Monokai,
        _ => Theme::Fruity,
    });
    let response_charset = s("response_charset").and_then(|c| Encoding::for_label(&c));
    let print = s("print").map(|p| Print::from_format(&p));
    let history_print = s("history_print").map(|p| Print::from_format(&p));

    let auth_type = s("auth_type").map(|a| match a.as_str() {
        "basic" => AuthType::Basic,
        "bearer" => AuthType::Bearer,
        _ => AuthType::Digest,
    });

    let session_read_only = s("session_read_only");
    let (session, is_session_read_only) = match (s("session"), session_read_only) {
        (Some(s), _) => (Some(s), false),
        (None, Some(s)) => (Some(s), true),
        (None, None) => (None, false),
    };

    let timeout = s("timeout").map(|t| {
        let secs: f64 = t.parse().unwrap_or(0.0);
        Timeout(Duration::from_secs_f64(secs))
    });

    let mut proxy = Vec::new();
    if let Some(values) = matches.get_many::<String>("proxy") {
        for v in values {
            let (protocol, url) = v.split_once(':').unwrap();
            let url = Url::parse(url).unwrap();
            proxy.push(match protocol.to_lowercase().as_str() {
                "http" => Proxy::Http(url),
                "https" => Proxy::Https(url),
                _ => Proxy::All(url),
            });
        }
    }

    let verify = s("verify").map(|v| match v.to_lowercase().as_str() {
        "no" | "false" => Verify::No,
        "yes" | "true" => Verify::Yes,
        _ => Verify::CustomCaBundle(PathBuf::from(v)),
    });

    let ssl = s("ssl").and_then(|v| match v.as_str() {
        "tls1" => Some(TlsVersion::Tls1),
        "tls1.1" => Some(TlsVersion::Tls1_1),
        "tls1.2" => Some(TlsVersion::Tls1_2),
        "tls1.3" => Some(TlsVersion::Tls1_3),
        _ => None,
    });

    let http_version = s("http_version").map(|v| match v.as_str() {
        "1.0" => HttpVersion::Http10,
        "1.1" => HttpVersion::Http11,
        "2" => HttpVersion::Http2,
        "2-prior-knowledge" => HttpVersion::Http2PriorKnowledge,
        _ => HttpVersion::Http3PriorKnowledge,
    });

    let mut resolve = Vec::new();
    if let Some(values) = matches.get_many::<String>("resolve") {
        for v in values {
            let (domain, addr) = v.rsplit_once(':').unwrap();
            resolve.push(Resolve { domain: domain.to_string(), addr: addr.parse().unwrap() });
        }
    }

    let check_status_raw = flag("check_status");
    let check_status = if check_status_raw { Some(true) } else { None };
    let stream = if flag("stream") { Some(true) } else { None };

    let mut cli = Cli {
        httpie_compat_mode,
        json: flag("json"),
        form: flag("form"),
        multipart: flag("multipart"),
        raw,
        pretty,
        format_options,
        style,
        response_charset,
        response_mime: s("response_mime"),
        print,
        headers: flag("headers"),
        body: flag("body"),
        meta: flag("meta"),
        verbose: count("verbose"),
        debug: flag("debug"),
        all: flag("all"),
        history_print,
        quiet: count("quiet"),
        stream,
        compress: count("compress"),
        output: matches.get_one::<PathBuf>("output").cloned(),
        download: flag("download"),
        resume: flag("continue"),
        session,
        is_session_read_only,
        auth_type,
        auth: s("auth"),
        bearer: s("bearer"),
        ignore_netrc: flag("ignore_netrc"),
        offline: flag("offline"),
        check_status,
        follow: flag("follow"),
        max_redirects: matches.get_one::<usize>("max_redirects").copied(),
        timeout,
        proxy,
        verify,
        cert: matches.get_one::<PathBuf>("cert").cloned(),
        cert_key: matches.get_one::<PathBuf>("cert_key").cloned(),
        ssl,
        native_tls: flag("native_tls"),
        default_scheme,
        https,
        http_version,
        resolve,
        interface: s("interface"),
        ipv4: flag("ipv4"),
        ipv6: flag("ipv6"),
        unix_socket: matches.get_one::<PathBuf>("unix_socket").cloned(),
        ignore_stdin: flag("ignore_stdin"),
        curl: flag("curl"),
        curl_long: flag("curl_long"),
        generate: None,
        raw_method_or_url,
        raw_rest_args,
        method,
        url,
        request_items,
        bin_name: bin_name.to_string(),
    };

    // --json/--form/--multipart: the last one wins
    cli.normalize_body_flags(matches);

    Ok(Parsed::Run(Box::new(cli)))
}

impl Cli {
    fn normalize_body_flags(&mut self, matches: &ArgMatches) {
        // Determine which of --json/--form/--multipart was given last.
        let idx = |name: &str| -> Option<usize> {
            if matches.get_flag(name) {
                matches.index_of(name)
            } else {
                None
            }
        };
        let candidates = [("json", idx("json")), ("form", idx("form")), ("multipart", idx("multipart"))];
        let winner = candidates
            .iter()
            .filter_map(|(n, i)| i.map(|i| (*n, i)))
            .max_by_key(|(_, i)| *i)
            .map(|(n, _)| n);
        self.json = winner == Some("json");
        self.form = winner == Some("form");
        self.multipart = winner == Some("multipart");
    }

    pub fn body_type(&self) -> BodyType {
        if self.multipart {
            BodyType::Multipart
        } else if self.form {
            BodyType::Form
        } else {
            BodyType::Json
        }
    }

    pub fn format_options(&self) -> FormatOptions {
        let mut merged = FormatOptions::default();
        for o in &self.format_options {
            if o.json_indent.is_some() {
                merged.json_indent = o.json_indent;
            }
            if o.json_format.is_some() {
                merged.json_format = o.json_format;
            }
            if o.headers_sort.is_some() {
                merged.headers_sort = o.headers_sort;
            }
        }
        merged
    }
}
