//! URL construction from the user supplied argument.

use url::Url;

pub fn construct_url(url: &str, default_scheme: &str, query: &[(String, String)]) -> Result<Url, url::ParseError> {
    let mut scheme = default_scheme.to_string();
    if !scheme.ends_with("://") {
        scheme.push_str("://");
    }
    let mut parsed: Url = if let Some(rest) = url.strip_prefix("://") {
        format!("{}{}", scheme, rest).parse()?
    } else if url.starts_with(':') {
        format!("{}localhost{}", scheme, url).parse()?
    } else if !has_scheme(url) {
        format!("{}{}", scheme, url).parse()?
    } else {
        url.parse()?
    };
    if !query.is_empty() {
        let mut pairs = parsed.query_pairs_mut();
        for (k, v) in query {
            pairs.append_pair(k, v);
        }
    }
    Ok(parsed)
}

/// Matches `[a-zA-Z0-9]://.+`
fn has_scheme(url: &str) -> bool {
    match url.find("://") {
        Some(i) if i > 0 => {
            let before = url[..i].chars().last().unwrap();
            before.is_ascii_alphanumeric() && url.len() > i + 3
        }
        _ => false,
    }
}
