//! Body readers for the different HTTP/1.1 framing modes.

use std::io::{self, BufRead, BufReader, Read};

/// Error kinds produced while reading a body from the connection.
fn body_error(msg: &str) -> io::Error {
    io::Error::new(io::ErrorKind::UnexpectedEof, msg.to_string())
}

/// Reads exactly `remaining` bytes from the underlying stream.
pub struct LengthReader<R> {
    inner: R,
    remaining: u64,
}

impl<R: Read> LengthReader<R> {
    pub fn new(inner: R, len: u64) -> Self {
        LengthReader { inner, remaining: len }
    }
}

impl<R: Read> Read for LengthReader<R> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.remaining == 0 {
            return Ok(0);
        }
        let max = buf.len().min(self.remaining as usize);
        let n = self.inner.read(&mut buf[..max])?;
        if n == 0 {
            return Err(body_error("end of file before message length reached"));
        }
        self.remaining -= n as u64;
        Ok(n)
    }
}

/// Decodes a `Transfer-Encoding: chunked` body.
pub struct ChunkedReader<R: Read> {
    inner: BufReader<R>,
    chunk_remaining: u64,
    done: bool,
    started: bool,
}

impl<R: Read> ChunkedReader<R> {
    pub fn new(inner: BufReader<R>) -> Self {
        ChunkedReader { inner, chunk_remaining: 0, done: false, started: false }
    }

    fn read_line(&mut self) -> io::Result<String> {
        let mut line = Vec::new();
        let n = self.inner.read_until(b'\n', &mut line)?;
        if n == 0 {
            return Err(body_error("end of file before message length reached"));
        }
        while line.last().map_or(false, |&b| b == b'\n' || b == b'\r') {
            line.pop();
        }
        Ok(String::from_utf8_lossy(&line).into_owned())
    }

    fn next_chunk(&mut self) -> io::Result<()> {
        if self.started {
            // consume CRLF after the previous chunk
            let line = self.read_line()?;
            if !line.is_empty() {
                return Err(io::Error::new(io::ErrorKind::InvalidData, "invalid chunk end"));
            }
        }
        self.started = true;
        let line = self.read_line()?;
        let size_str = line.split(';').next().unwrap_or("").trim();
        let size = u64::from_str_radix(size_str, 16)
            .map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "invalid chunk size"))?;
        if size == 0 {
            // trailers
            loop {
                let line = self.read_line()?;
                if line.is_empty() {
                    break;
                }
            }
            self.done = true;
        }
        self.chunk_remaining = size;
        Ok(())
    }
}

impl<R: Read> Read for ChunkedReader<R> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.done {
            return Ok(0);
        }
        if self.chunk_remaining == 0 {
            self.next_chunk()?;
            if self.done {
                return Ok(0);
            }
        }
        let max = buf.len().min(self.chunk_remaining as usize);
        let n = self.inner.read(&mut buf[..max])?;
        if n == 0 {
            return Err(body_error("end of file before message length reached"));
        }
        self.chunk_remaining -= n as u64;
        Ok(n)
    }
}

/// Reads until the connection is closed.
pub struct CloseDelimitedReader<R> {
    inner: R,
}

impl<R: Read> CloseDelimitedReader<R> {
    pub fn new(inner: R) -> Self {
        CloseDelimitedReader { inner }
    }
}

impl<R: Read> Read for CloseDelimitedReader<R> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        self.inner.read(buf)
    }
}

/// An empty body.
pub struct EmptyReader;

impl Read for EmptyReader {
    fn read(&mut self, _buf: &mut [u8]) -> io::Result<usize> {
        Ok(0)
    }
}
