/// An error with a chain of causes, formatted like `anyhow` does.
#[derive(Debug)]
pub struct ChainError {
    msg: String,
    source: Option<Box<dyn std::error::Error + Send + Sync>>,
}

impl ChainError {
    pub fn new(msg: impl Into<String>) -> ChainError {
        ChainError { msg: msg.into(), source: None }
    }

    pub fn with_source(msg: impl Into<String>, source: impl std::error::Error + Send + Sync + 'static) -> ChainError {
        ChainError { msg: msg.into(), source: Some(Box::new(source)) }
    }

    /// Build a chain from a list of messages ending in the given error.
    pub fn chain(msgs: &[&str], source: impl std::error::Error + Send + Sync + 'static) -> ChainError {
        let mut err: Box<dyn std::error::Error + Send + Sync> = Box::new(source);
        for msg in msgs.iter().rev() {
            err = Box::new(ChainError { msg: msg.to_string(), source: Some(err) });
        }
        match err.downcast::<ChainError>() {
            Ok(e) => *e,
            Err(e) => ChainError { msg: e.to_string(), source: None },
        }
    }
}

impl fmt::Display for ChainError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.msg)
    }
}

impl std::error::Error for ChainError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        self.source.as_ref().map(|e| e.as_ref() as &(dyn std::error::Error + 'static))
    }
}

/// Marker error used to select the exit code for timeouts.
#[derive(Debug)]
pub struct TimedOut;

impl fmt::Display for TimedOut {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("operation timed out")
    }
}

impl std::error::Error for TimedOut {}

pub enum Stream {
    Tcp(TcpStream),
    Tls(TlsStream),
    Unix(UnixStream),
}

impl Read for Stream {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self {
            Stream::Tcp(s) => s.read(buf),
            Stream::Tls(s) => s.read(buf),
            Stream::Unix(s) => s.read(buf),
        }
    }
}

impl Write for Stream {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self {
            Stream::Tcp(s) => s.write(buf),
            Stream::Tls(s) => s.write(buf),
            Stream::Unix(s) => s.write(buf),
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        match self {
            Stream::Tcp(s) => s.flush(),
            Stream::Tls(s) => s.flush(),
            Stream::Unix(s) => s.flush(),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IpFilter {
    Any,
    V4Only,
    V6Only,
}

#[derive(Debug, Clone)]
pub struct ProxyConfig {
    pub http: Option<url::Url>,
    pub https: Option<url::Url>,
    pub no_proxy: Vec<String>,
}

pub struct Client {
    pub timeout: Option<Duration>,
    pub resolve: Vec<Resolve>,
    pub ip_filter: IpFilter,
    pub unix_socket: Option<PathBuf>,
    pub interface: Option<String>,
    pub tls: TlsConfig,
    pub proxy: ProxyConfig,
    pub http_version: Option<crate::args::HttpVersion>,
}

impl Client {
    pub fn new() -> Client {
        Client {
            timeout: None,
            resolve: Vec::new(),
            ip_filter: IpFilter::Any,
            unix_socket: None,
            interface: None,
            tls: TlsConfig {
                verify: Verify::Yes,
                cert: None,
                cert_key: None,
                version: None,
            },
            proxy: ProxyConfig { http: None, https: None, no_proxy: Vec::new() },
            http_version: None,
        }
    }

    fn deadline(&self) -> Option<Instant> {
        self.timeout.map(|t| Instant::now() + t)
    }

    fn resolve_addrs(&self, host: &str, port: u16) -> io::Result<Vec<SocketAddr>> {
        if let Some(r) = self.resolve.iter().find(|r| r.domain.eq_ignore_ascii_case(host)) {
            return Ok(vec![SocketAddr::new(r.addr, port)]);
        }
        let host = host.trim_start_matches('[').trim_end_matches(']');
        if let Ok(ip) = host.parse::<IpAddr>() {
            return Ok(vec![SocketAddr::new(ip, port)]);
        }
        let addrs: Vec<SocketAddr> = (host, port).to_socket_addrs()?.collect();
        let filtered: Vec<SocketAddr> = addrs
            .into_iter()
            .filter(|a| match self.ip_filter {
                IpFilter::Any => true,
                IpFilter::V4Only => a.is_ipv4(),
                IpFilter::V6Only => a.is_ipv6(),
            })
            .collect();
        Ok(filtered)
    }

    fn connect_tcp(&self, host: &str, port: u16, deadline: Option<Instant>) -> Result<TcpStream, ChainError> {
        let addrs = self
            .resolve_addrs(host, port)
            .map_err(|e| ChainError::chain(&["client error (Connect)", "dns error"], e))?;
        if addrs.is_empty() {
            return Err(ChainError::chain(
                &["client error (Connect)", "dns error"],
                io::Error::new(io::ErrorKind::Other, "no addresses found"),
            ));
        }
        // Prefer IPv4 addresses first like most clients do when IPv6 is unreachable.
        let mut last_err: Option<io::Error> = None;
        for addr in &addrs {
            if let Some(d) = deadline {
                if Instant::now() >= d {
                    return Err(ChainError::with_source("operation timed out", TimedOut));
                }
            }
            let result = match (&self.interface, deadline) {
                (Some(iface), _) => connect_bound(addr, iface, deadline),
                (None, Some(d)) => {
                    let remaining = d.saturating_duration_since(Instant::now());
                    TcpStream::connect_timeout(addr, remaining.max(Duration::from_millis(1)))
                }
                (None, None) => TcpStream::connect(addr),
            };
            match result {
                Ok(stream) => {
                    let _ = stream.set_nodelay(true);
                    return Ok(stream);
                }
                Err(e) => {
                    if e.kind() == io::ErrorKind::TimedOut {
                        return Err(ChainError::with_source("operation timed out", TimedOut));
                    }
                    last_err = Some(e)
                }
            }
        }
        Err(ChainError::chain(
            &["client error (Connect)", "tcp connect error"],
            last_err.unwrap(),
        ))
    }

    fn proxy_for(&self, url: &url::Url) -> Option<&url::Url> {
        let host = url.host_str().unwrap_or("");
        for pattern in &self.proxy.no_proxy {
            let p = pattern.trim();
            if p.is_empty() {
                continue;
            }
            if p == "*" || host.eq_ignore_ascii_case(p) || host.to_ascii_lowercase().ends_with(&format!(".{}", p.trim_start_matches('.').to_ascii_lowercase())) {
                return None;
            }
        }
        match url.scheme() {
            "https" => self.proxy.https.as_ref(),
            _ => self.proxy.http.as_ref(),
        }
    }

    fn open_stream(&self, url: &url::Url, deadline: Option<Instant>) -> Result<(Stream, Option<SocketAddr>, bool), ChainError> {
        let scheme = url.scheme();
        if let Some(path) = &self.unix_socket {
            let stream = UnixStream::connect(path)
                .map_err(|e| ChainError::chain(&["client error (Connect)"], e))?;
            if let Some(t) = self.timeout {
                let _ = stream.set_read_timeout(Some(t));
                let _ = stream.set_write_timeout(Some(t));
            }
            return Ok((Stream::Unix(stream), None, false));
        }
        let host = url.host_str().unwrap_or("").to_string();
        let port = url.port_or_known_default().unwrap_or(80);
        let is_https = scheme == "https";

        if let Some(proxy) = self.proxy_for(url) {
            let phost = proxy.host_str().unwrap_or("").to_string();
            let pport = proxy.port_or_known_default().unwrap_or(8080);
            let tcp = self.connect_tcp(&phost, pport, deadline)?;
            if let Some(t) = self.timeout {
                let _ = tcp.set_read_timeout(Some(t));
                let _ = tcp.set_write_timeout(Some(t));
            }
            let addr = tcp.peer_addr().ok();
            let mut stream = if proxy.scheme() == "https" {
                Stream::Tls(self.tls.connect(tcp, &phost).map_err(|e| ChainError::chain(&["client error (Connect)"], e))?)
            } else {
                Stream::Tcp(tcp)
            };
            if is_https {
                // CONNECT tunnel
                let mut req = format!("CONNECT {}:{} HTTP/1.1\r\nHost: {}:{}\r\n", host, port, host, port);
                if let Some(auth) = proxy_authorization(proxy) {
                    req.push_str(&format!("Proxy-Authorization: {}\r\n", auth));
                }
                req.push_str("\r\n");
                stream
                    .write_all(req.as_bytes())
                    .map_err(|e| ChainError::chain(&["client error (Connect)"], e))?;
                let mut reader = BufReader::new(&mut stream);
                let (_, status, _, _) = read_head(&mut reader)
                    .map_err(|e| ChainError::chain(&["client error (Connect)"], e))?;
                if !(200..300).contains(&status) {
                    return Err(ChainError::chain(
                        &["client error (Connect)"],
                        io::Error::new(io::ErrorKind::Other, format!("unsuccessful tunnel ({})", status)),
                    ));
                }
                let tcp = match stream {
                    Stream::Tcp(t) => t,
                    _ => return Err(ChainError::new("https proxy for https target is not supported")),
                };
                let tls = self.tls.connect(tcp, &host).map_err(|e| ChainError::chain(&["client error (Connect)"], e))?;
                return Ok((Stream::Tls(tls), addr, false));
            }
            return Ok((stream, addr, true));
        }

        let tcp = self.connect_tcp(&host, port, deadline)?;
        if let Some(t) = self.timeout {
            let _ = tcp.set_read_timeout(Some(t));
            let _ = tcp.set_write_timeout(Some(t));
        }
        let addr = tcp.peer_addr().ok();
        if is_https {
            let tls = self.tls.connect(tcp, &host).map_err(|e| ChainError::chain(&["client error (Connect)"], e))?;
            Ok((Stream::Tls(tls), addr, false))
        } else {
            Ok((Stream::Tcp(tcp), addr, false))
        }
    }

    /// Send a request and read the response head. The body remains unread.
    pub fn send(&self, request: &Request) -> Result<Response, ChainError> {
        let deadline = self.deadline();
        let (mut stream, remote_addr, via_proxy) = self.open_stream(&request.url, deadline)?;

        let mut out = Vec::new();
        let target = if via_proxy {
            let mut u = request.url.clone();
            u.set_fragment(None);
            u.to_string()
        } else {
            request.path_and_query()
        };
        let version = match request.version {
            Version::Http10 => "HTTP/1.0",
            _ => "HTTP/1.1",
        };
        out.extend_from_slice(format!("{} {} {}\r\n", request.method, target, version).as_bytes());
        for (name, value) in request.headers.iter() {
            out.extend_from_slice(name.titled().as_bytes());
            out.extend_from_slice(b": ");
            out.extend_from_slice(value);
            out.extend_from_slice(b"\r\n");
        }
        if !request.headers.contains_key("host") {
            out.extend_from_slice(format!("Host: {}\r\n", request.host_header()).as_bytes());
        }
        if via_proxy {
            if let Some(proxy) = self.proxy_for(&request.url) {
                if let Some(auth) = proxy_authorization(proxy) {
                    out.extend_from_slice(format!("Proxy-Authorization: {}\r\n", auth).as_bytes());
                }
            }
        }
        out.extend_from_slice(b"\r\n");
        out.extend_from_slice(request.body.as_bytes());

        stream.write_all(&out).map_err(|e| map_io_error(e, "client error (SendRequest)"))?;
        stream.flush().map_err(|e| map_io_error(e, "client error (SendRequest)"))?;

        let mut reader = BufReader::with_capacity(64 * 1024, stream);
        let (version, status, reason, headers) =
            read_head(&mut reader).map_err(|e| map_io_error(e, "client error (SendRequest)"))?;

        let has_body = !(request.method == "HEAD"
            || (100..200).contains(&status)
            || status == 204
            || status == 304);
        let body: Box<dyn Read + Send> = if !has_body {
            Box::new(EmptyReader)
        } else if headers
            .get_str("transfer-encoding")
            .map_or(false, |te| te.to_ascii_lowercase().contains("chunked"))
        {
            Box::new(ChunkedReader::new(reader))
        } else if let Some(len) = headers.get_str("content-length") {
            let len: u64 = len
                .trim()
                .parse()
                .map_err(|_| ChainError::chain(&["client error (SendRequest)"], io::Error::new(io::ErrorKind::InvalidData, "invalid content-length parsed")))?;
            Box::new(LengthReader::new(reader, len))
        } else {
            Box::new(CloseDelimitedReader::new(reader))
        };

        Ok(Response { version, status, reason, headers, body, remote_addr })
    }
}

fn map_io_error(e: io::Error, context: &str) -> ChainError {
    if matches!(e.kind(), io::ErrorKind::TimedOut | io::ErrorKind::WouldBlock) {
        return ChainError::with_source("operation timed out", TimedOut);
    }
    ChainError::chain(&[context], e)
}

fn proxy_authorization(proxy: &url::Url) -> Option<String> {
    if proxy.username().is_empty() && proxy.password().is_none() {
        return None;
    }
    use base64::Engine;
    let user = percent_encoding::percent_decode_str(proxy.username()).decode_utf8_lossy();
    let pass = percent_encoding::percent_decode_str(proxy.password().unwrap_or("")).decode_utf8_lossy();
    Some(format!(
        "Basic {}",
        base64::engine::general_purpose::STANDARD.encode(format!("{}:{}", user, pass))
    ))
}

fn connect_bound(addr: &SocketAddr, iface: &str, deadline: Option<Instant>) -> io::Result<TcpStream> {
    use std::os::fd::FromRawFd;
    // Interface may be an IP address or a device name.
    let local_ip: Option<IpAddr> = iface.parse().ok();
    let domain = if addr.is_ipv4() { libc::AF_INET } else { libc::AF_INET6 };
    let fd = unsafe { libc::socket(domain, libc::SOCK_STREAM | libc::SOCK_CLOEXEC, 0) };
    if fd < 0 {
        return Err(io::Error::last_os_error());
    }
    let sock = unsafe { TcpStream::from_raw_fd(fd) };
    if let Some(ip) = local_ip {
        let local = SocketAddr::new(ip, 0);
        bind_socket(fd, &local)?;
    } else {
        let name = std::ffi::CString::new(iface).map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid interface"))?;
        let rc = unsafe {
            libc::setsockopt(
                fd,
                libc::SOL_SOCKET,
                libc::SO_BINDTODEVICE,
                name.as_ptr() as *const libc::c_void,
                name.as_bytes_with_nul().len() as libc::socklen_t,
            )
        };
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }
    }
    connect_fd(fd, addr, deadline)?;
    Ok(sock)
}

fn sockaddr_storage(addr: &SocketAddr) -> (libc::sockaddr_storage, libc::socklen_t) {
    let mut storage: libc::sockaddr_storage = unsafe { std::mem::zeroed() };
    let len = match addr {
        SocketAddr::V4(a) => {
            let sin = libc::sockaddr_in {
                sin_family: libc::AF_INET as libc::sa_family_t,
                sin_port: a.port().to_be(),
                sin_addr: libc::in_addr { s_addr: u32::from_ne_bytes(a.ip().octets()) },
                sin_zero: [0; 8],
            };
            unsafe { std::ptr::write(&mut storage as *mut _ as *mut libc::sockaddr_in, sin) };
            std::mem::size_of::<libc::sockaddr_in>()
        }
        SocketAddr::V6(a) => {
            let sin6 = libc::sockaddr_in6 {
                sin6_family: libc::AF_INET6 as libc::sa_family_t,
                sin6_port: a.port().to_be(),
                sin6_flowinfo: a.flowinfo(),
                sin6_addr: libc::in6_addr { s6_addr: a.ip().octets() },
                sin6_scope_id: a.scope_id(),
            };
            unsafe { std::ptr::write(&mut storage as *mut _ as *mut libc::sockaddr_in6, sin6) };
            std::mem::size_of::<libc::sockaddr_in6>()
        }
    };
    (storage, len as libc::socklen_t)
}

fn bind_socket(fd: i32, addr: &SocketAddr) -> io::Result<()> {
    let (storage, len) = sockaddr_storage(addr);
    let rc = unsafe { libc::bind(fd, &storage as *const _ as *const libc::sockaddr, len) };
    if rc != 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

fn connect_fd(fd: i32, addr: &SocketAddr, deadline: Option<Instant>) -> io::Result<()> {
    let (storage, len) = sockaddr_storage(addr);
    if let Some(d) = deadline {
        // non-blocking connect with poll
        unsafe {
            let flags = libc::fcntl(fd, libc::F_GETFL);
            libc::fcntl(fd, libc::F_SETFL, flags | libc::O_NONBLOCK);
        }
        let rc = unsafe { libc::connect(fd, &storage as *const _ as *const libc::sockaddr, len) };
        if rc != 0 {
            let err = io::Error::last_os_error();
            if err.raw_os_error() != Some(libc::EINPROGRESS) {
                return Err(err);
            }
            let remaining = d.saturating_duration_since(Instant::now());
            let mut pfd = libc::pollfd { fd, events: libc::POLLOUT, revents: 0 };
            let prc = unsafe { libc::poll(&mut pfd, 1, remaining.as_millis() as i32) };
            if prc == 0 {
                return Err(io::Error::new(io::ErrorKind::TimedOut, "connection timed out"));
            }
            if prc < 0 {
                return Err(io::Error::last_os_error());
            }
            let mut err: libc::c_int = 0;
            let mut elen = std::mem::size_of::<libc::c_int>() as libc::socklen_t;
            unsafe {
                libc::getsockopt(fd, libc::SOL_SOCKET, libc::SO_ERROR, &mut err as *mut _ as *mut libc::c_void, &mut elen);
            }
            if err != 0 {
                return Err(io::Error::from_raw_os_error(err));
            }
        }
        unsafe {
            let flags = libc::fcntl(fd, libc::F_GETFL);
            libc::fcntl(fd, libc::F_SETFL, flags & !libc::O_NONBLOCK);
        }
        Ok(())
    } else {
        let rc = unsafe { libc::connect(fd, &storage as *const _ as *const libc::sockaddr, len) };
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(())
    }
}

/// Parse the status line and headers of a response.
pub fn read_head<R: Read>(reader: &mut BufReader<R>) -> io::Result<(Version, u16, String, HeaderMap)> {
    let mut line = Vec::new();
    let n = reader.read_until(b'\n', &mut line)?;
    if n == 0 {
        return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "connection closed before message completed"));
    }
    strip_crlf(&mut line);
    let line_str = String::from_utf8_lossy(&line).into_owned();
    let mut parts = line_str.splitn(3, ' ');
    let version = match parts.next() {
        Some("HTTP/1.1") => Version::Http11,
        Some("HTTP/1.0") => Version::Http10,
        Some(v) if v.starts_with("HTTP/") => Version::Http11,
        _ => return Err(io::Error::new(io::ErrorKind::InvalidData, "invalid HTTP version parsed")),
    };
    let status: u16 = parts
        .next()
        .and_then(|s| s.parse().ok())
        .filter(|s| (100..1000).contains(s))
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "invalid HTTP status-code parsed"))?;
    let reason = parts.next().unwrap_or("").to_string();

    let mut headers = HeaderMap::new();
    loop {
        let mut line = Vec::new();
        let n = reader.read_until(b'\n', &mut line)?;
        if n == 0 {
            return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "connection closed before message completed"));
        }
        strip_crlf(&mut line);
        if line.is_empty() {
            break;
        }
        let colon = match line.iter().position(|&b| b == b':') {
            Some(c) => c,
            None => return Err(io::Error::new(io::ErrorKind::InvalidData, "invalid HTTP header parsed")),
        };
        let name = String::from_utf8_lossy(&line[..colon]).into_owned();
        let name = HeaderName::new(name.trim())
            .map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "invalid HTTP header parsed"))?;
        let mut value = &line[colon + 1..];
        while value.first().map_or(false, |b| *b == b' ' || *b == b'\t') {
            value = &value[1..];
        }
        while value.last().map_or(false, |b| *b == b' ' || *b == b'\t') {
            value = &value[..value.len() - 1];
        }
        headers.append(name, value.to_vec());
    }
    Ok((version, status, reason, headers))
}

fn strip_crlf(line: &mut Vec<u8>) {
    while line.last().map_or(false, |&b| b == b'\n' || b == b'\r') {
        line.pop();
    }
}

