pub fn tls_version_name(v: TlsVersion) -> &'static str {
    match v {
        TlsVersion::Tls1 => "tls1",
        TlsVersion::Tls1_1 => "tls1.1",
        TlsVersion::Tls1_2 => "tls1.2",
        TlsVersion::Tls1_3 => "tls1.3",
    }
}
