//! TLS support through the system OpenSSL library, loaded at runtime.

use std::ffi::{c_char, c_int, c_long, c_uchar, c_uint, c_ulong, c_void, CString};
use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::os::fd::AsRawFd;
use std::path::PathBuf;
use std::sync::OnceLock;

use crate::args::{TlsVersion, Verify};

#[derive(Debug, Clone)]
pub struct TlsConfig {
    pub verify: Verify,
    pub cert: Option<PathBuf>,
    pub cert_key: Option<PathBuf>,
    pub version: Option<TlsVersion>,
}

type SslCtx = c_void;
type Ssl = c_void;

#[allow(non_snake_case)]
struct Api {
    SSL_CTX_new: unsafe extern "C" fn(*const c_void) -> *mut SslCtx,
    TLS_client_method: unsafe extern "C" fn() -> *const c_void,
    SSL_CTX_set_default_verify_paths: unsafe extern "C" fn(*mut SslCtx) -> c_int,
    SSL_CTX_load_verify_locations: unsafe extern "C" fn(*mut SslCtx, *const c_char, *const c_char) -> c_int,
    SSL_CTX_set_verify: unsafe extern "C" fn(*mut SslCtx, c_int, *const c_void),
    SSL_CTX_use_certificate_chain_file: unsafe extern "C" fn(*mut SslCtx, *const c_char) -> c_int,
    SSL_CTX_use_PrivateKey_file: unsafe extern "C" fn(*mut SslCtx, *const c_char, c_int) -> c_int,
    SSL_CTX_ctrl: unsafe extern "C" fn(*mut SslCtx, c_int, c_long, *mut c_void) -> c_long,
    SSL_CTX_set_alpn_protos: unsafe extern "C" fn(*mut SslCtx, *const c_uchar, c_uint) -> c_int,
    SSL_CTX_free: unsafe extern "C" fn(*mut SslCtx),
    SSL_new: unsafe extern "C" fn(*mut SslCtx) -> *mut Ssl,
    SSL_set_fd: unsafe extern "C" fn(*mut Ssl, c_int) -> c_int,
    SSL_ctrl: unsafe extern "C" fn(*mut Ssl, c_int, c_long, *mut c_void) -> c_long,
    SSL_set1_host: unsafe extern "C" fn(*mut Ssl, *const c_char) -> c_int,
    SSL_connect: unsafe extern "C" fn(*mut Ssl) -> c_int,
    SSL_read: unsafe extern "C" fn(*mut Ssl, *mut c_void, c_int) -> c_int,
    SSL_write: unsafe extern "C" fn(*mut Ssl, *const c_void, c_int) -> c_int,
    SSL_get_error: unsafe extern "C" fn(*const Ssl, c_int) -> c_int,
    SSL_shutdown: unsafe extern "C" fn(*mut Ssl) -> c_int,
    SSL_free: unsafe extern "C" fn(*mut Ssl),
    SSL_get_verify_result: unsafe extern "C" fn(*const Ssl) -> c_long,
    X509_verify_cert_error_string: unsafe extern "C" fn(c_long) -> *const c_char,
    ERR_get_error: unsafe extern "C" fn() -> c_ulong,
    ERR_error_string_n: unsafe extern "C" fn(c_ulong, *mut c_char, usize),
}

static API: OnceLock<Option<Api>> = OnceLock::new();

unsafe fn load_sym<T>(handles: &[*mut c_void], name: &str) -> Option<T> {
    let cname = CString::new(name).ok()?;
    for &h in handles {
        let sym = libc::dlsym(h, cname.as_ptr());
        if !sym.is_null() {
            return Some(std::mem::transmute_copy(&sym));
        }
    }
    None
}

fn load_api() -> Option<Api> {
    unsafe {
        let mut handles = Vec::new();
        for lib in ["libssl.so.3", "libssl.so.1.1", "libssl.so"] {
            let c = CString::new(lib).unwrap();
            let h = libc::dlopen(c.as_ptr(), libc::RTLD_NOW | libc::RTLD_GLOBAL);
            if !h.is_null() {
                handles.push(h);
                break;
            }
        }
        if handles.is_empty() {
            return None;
        }
        for lib in ["libcrypto.so.3", "libcrypto.so.1.1", "libcrypto.so"] {
            let c = CString::new(lib).unwrap();
            let h = libc::dlopen(c.as_ptr(), libc::RTLD_NOW | libc::RTLD_GLOBAL);
            if !h.is_null() {
                handles.push(h);
                break;
            }
        }
        macro_rules! sym {
            ($name:ident) => {
                load_sym(&handles, stringify!($name))?
            };
        }
        Some(Api {
            SSL_CTX_new: sym!(SSL_CTX_new),
            TLS_client_method: sym!(TLS_client_method),
            SSL_CTX_set_default_verify_paths: sym!(SSL_CTX_set_default_verify_paths),
            SSL_CTX_load_verify_locations: sym!(SSL_CTX_load_verify_locations),
            SSL_CTX_set_verify: sym!(SSL_CTX_set_verify),
            SSL_CTX_use_certificate_chain_file: sym!(SSL_CTX_use_certificate_chain_file),
            SSL_CTX_use_PrivateKey_file: sym!(SSL_CTX_use_PrivateKey_file),
            SSL_CTX_ctrl: sym!(SSL_CTX_ctrl),
            SSL_CTX_set_alpn_protos: sym!(SSL_CTX_set_alpn_protos),
            SSL_CTX_free: sym!(SSL_CTX_free),
            SSL_new: sym!(SSL_new),
            SSL_set_fd: sym!(SSL_set_fd),
            SSL_ctrl: sym!(SSL_ctrl),
            SSL_set1_host: sym!(SSL_set1_host),
            SSL_connect: sym!(SSL_connect),
            SSL_read: sym!(SSL_read),
            SSL_write: sym!(SSL_write),
            SSL_get_error: sym!(SSL_get_error),
            SSL_shutdown: sym!(SSL_shutdown),
            SSL_free: sym!(SSL_free),
            SSL_get_verify_result: sym!(SSL_get_verify_result),
            X509_verify_cert_error_string: sym!(X509_verify_cert_error_string),
            ERR_get_error: sym!(ERR_get_error),
            ERR_error_string_n: sym!(ERR_error_string_n),
        })
    }
}

fn api() -> io::Result<&'static Api> {
    API.get_or_init(load_api)
        .as_ref()
        .ok_or_else(|| io::Error::new(io::ErrorKind::Unsupported, "TLS support is unavailable (OpenSSL could not be loaded)"))
}

const SSL_CTRL_SET_TLSEXT_HOSTNAME: c_int = 55;
const SSL_CTRL_SET_MIN_PROTO_VERSION: c_int = 123;
const SSL_CTRL_SET_MAX_PROTO_VERSION: c_int = 124;
const SSL_VERIFY_NONE: c_int = 0;
const SSL_VERIFY_PEER: c_int = 1;
const SSL_FILETYPE_PEM: c_int = 1;
const SSL_ERROR_ZERO_RETURN: c_int = 6;
const SSL_ERROR_SYSCALL: c_int = 5;

fn last_error_string(api: &Api) -> String {
    let code = unsafe { (api.ERR_get_error)() };
    if code == 0 {
        return String::new();
    }
    let mut buf = vec![0 as c_char; 256];
    unsafe { (api.ERR_error_string_n)(code, buf.as_mut_ptr(), buf.len()) };
    let s = unsafe { std::ffi::CStr::from_ptr(buf.as_ptr()) };
    s.to_string_lossy().into_owned()
}

fn proto_code(v: TlsVersion) -> c_long {
    match v {
        TlsVersion::Tls1 => 0x0301,
        TlsVersion::Tls1_1 => 0x0302,
        TlsVersion::Tls1_2 => 0x0303,
        TlsVersion::Tls1_3 => 0x0304,
    }
}

pub struct TlsStream {
    api: &'static Api,
    ctx: *mut SslCtx,
    ssl: *mut Ssl,
    _tcp: TcpStream,
}

unsafe impl Send for TlsStream {}

impl TlsConfig {
    pub fn connect(&self, tcp: TcpStream, host: &str) -> io::Result<TlsStream> {
        let api = api()?;
        unsafe {
            let ctx = (api.SSL_CTX_new)((api.TLS_client_method)());
            if ctx.is_null() {
                return Err(io::Error::new(io::ErrorKind::Other, "failed to create TLS context"));
            }
            let fail = |msg: String| -> io::Error {
                (api.SSL_CTX_free)(ctx);
                io::Error::new(io::ErrorKind::Other, msg)
            };
            match &self.verify {
                Verify::No => (api.SSL_CTX_set_verify)(ctx, SSL_VERIFY_NONE, std::ptr::null()),
                Verify::Yes => {
                    (api.SSL_CTX_set_verify)(ctx, SSL_VERIFY_PEER, std::ptr::null());
                    (api.SSL_CTX_set_default_verify_paths)(ctx);
                }
                Verify::CustomCaBundle(path) => {
                    (api.SSL_CTX_set_verify)(ctx, SSL_VERIFY_PEER, std::ptr::null());
                    let c = CString::new(path.to_string_lossy().as_bytes()).unwrap();
                    if (api.SSL_CTX_load_verify_locations)(ctx, c.as_ptr(), std::ptr::null()) != 1 {
                        return Err(fail(format!("failed to load CA bundle {}: {}", path.display(), last_error_string(api))));
                    }
                }
            }
            if let Some(cert) = &self.cert {
                let c = CString::new(cert.to_string_lossy().as_bytes()).unwrap();
                if (api.SSL_CTX_use_certificate_chain_file)(ctx, c.as_ptr()) != 1 {
                    return Err(fail(format!("failed to load client certificate: {}", last_error_string(api))));
                }
                let key = self.cert_key.clone().unwrap_or_else(|| cert.clone());
                let k = CString::new(key.to_string_lossy().as_bytes()).unwrap();
                if (api.SSL_CTX_use_PrivateKey_file)(ctx, k.as_ptr(), SSL_FILETYPE_PEM) != 1 {
                    return Err(fail(format!("failed to load private key: {}", last_error_string(api))));
                }
            }
            if let Some(v) = self.version {
                (api.SSL_CTX_ctrl)(ctx, SSL_CTRL_SET_MIN_PROTO_VERSION, proto_code(v), std::ptr::null_mut());
                (api.SSL_CTX_ctrl)(ctx, SSL_CTRL_SET_MAX_PROTO_VERSION, proto_code(v), std::ptr::null_mut());
            }
            let alpn: &[u8] = b"\x08http/1.1";
            (api.SSL_CTX_set_alpn_protos)(ctx, alpn.as_ptr(), alpn.len() as c_uint);

            let ssl = (api.SSL_new)(ctx);
            if ssl.is_null() {
                return Err(fail("failed to create TLS session".to_string()));
            }
            let fail2 = |msg: String| -> io::Error {
                (api.SSL_free)(ssl);
                (api.SSL_CTX_free)(ctx);
                io::Error::new(io::ErrorKind::Other, msg)
            };
            (api.SSL_set_fd)(ssl, tcp.as_raw_fd());
            let is_ip = host.parse::<std::net::IpAddr>().is_ok() || host.starts_with('[');
            if !is_ip {
                let chost = CString::new(host).unwrap();
                (api.SSL_ctrl)(ssl, SSL_CTRL_SET_TLSEXT_HOSTNAME, 0, chost.as_ptr() as *mut c_void);
                if self.verify != Verify::No {
                    (api.SSL_set1_host)(ssl, chost.as_ptr());
                }
            }
            let rc = (api.SSL_connect)(ssl);
            if rc != 1 {
                let err = (api.SSL_get_error)(ssl, rc);
                let verify = (api.SSL_get_verify_result)(ssl);
                let msg = if verify != 0 {
                    let s = std::ffi::CStr::from_ptr((api.X509_verify_cert_error_string)(verify));
                    format!("invalid peer certificate: {}", s.to_string_lossy())
                } else if err == SSL_ERROR_SYSCALL {
                    let os = io::Error::last_os_error();
                    if os.raw_os_error() == Some(0) {
                        "received corrupt message of type Handshake".to_string()
                    } else {
                        os.to_string()
                    }
                } else {
                    let s = last_error_string(api);
                    if s.is_empty() { "TLS handshake failed".to_string() } else { s }
                };
                return Err(fail2(msg));
            }
            Ok(TlsStream { api, ctx, ssl, _tcp: tcp })
        }
    }
}

impl Read for TlsStream {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        let n = unsafe { (self.api.SSL_read)(self.ssl, buf.as_mut_ptr() as *mut c_void, buf.len().min(c_int::MAX as usize) as c_int) };
        if n > 0 {
            return Ok(n as usize);
        }
        let err = unsafe { (self.api.SSL_get_error)(self.ssl, n) };
        match err {
            SSL_ERROR_ZERO_RETURN => Ok(0),
            SSL_ERROR_SYSCALL => {
                let os = io::Error::last_os_error();
                if os.raw_os_error() == Some(0) || os.raw_os_error().is_none() {
                    Ok(0)
                } else {
                    Err(os)
                }
            }
            _ => Err(io::Error::new(io::ErrorKind::Other, last_error_string(self.api))),
        }
    }
}

impl Write for TlsStream {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        let n = unsafe { (self.api.SSL_write)(self.ssl, buf.as_ptr() as *const c_void, buf.len().min(c_int::MAX as usize) as c_int) };
        if n > 0 {
            Ok(n as usize)
        } else {
            let err = unsafe { (self.api.SSL_get_error)(self.ssl, n) };
            if err == SSL_ERROR_SYSCALL {
                Err(io::Error::last_os_error())
            } else {
                Err(io::Error::new(io::ErrorKind::Other, last_error_string(self.api)))
            }
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

impl Drop for TlsStream {
    fn drop(&mut self) {
        unsafe {
            (self.api.SSL_shutdown)(self.ssl);
            (self.api.SSL_free)(self.ssl);
            (self.api.SSL_CTX_free)(self.ctx);
        }
    }
}
