//! Syntax highlighting with ANSI escape codes for JSON and HTTP messages.

use std::io::{self, Write};
use std::sync::OnceLock;

use regex::Regex;

use crate::args::Theme;

/// Scopes used by the token producers.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Scope {
    Plain,
    Comment,
    JsonKey,
    String,
