/// Look up the style of a scope in a theme. The values mirror the bundled
/// `.tmTheme` files.
pub fn style_for(theme: Theme, scope: Scope) -> Style {
    let plain = |fg: u8| Style { fg, underline: false };
    match theme {
        Theme::Auto => match scope {
            Scope::Plain | Scope::Comment | Scope::HeaderValue | Scope::HttpSeparator => plain(0x07),
            Scope::Number => plain(0x04),
            Scope::Constant | Scope::Escape => plain(0x04),
            Scope::String => plain(0x03),
            Scope::Doctype => plain(0x06),
            Scope::TagName => plain(0x0C),
            Scope::AttributeName => plain(0x06),
            Scope::HeaderName => plain(0x06),
            Scope::HttpKeyword => plain(0x04),
            Scope::HttpReason => plain(0x06),
            Scope::HttpMethod => plain(0x02),
            Scope::HttpUrl => Style { fg: 0x06, underline: true },
            Scope::JsonKey => plain(0x0C),
            Scope::Error => plain(0x01),
        },
