            Scope::Comment => plain(0xF2),
            Scope::Doctype => plain(0xF2),
            Scope::TagName => plain(0xC5),
            Scope::AttributeName | Scope::HeaderName => plain(0x94),
            Scope::HttpKeyword => plain(0x51),
            Scope::HttpSeparator => plain(0xC5),
            Scope::HttpReason => plain(0x94),
            Scope::HttpMethod => plain(0xC5),
            Scope::JsonKey => plain(0xC5),
            Scope::Error => plain(0x01),
        },
        Theme::Fruity => match scope {
            Scope::Plain | Scope::HttpSeparator | Scope::HttpUrl | Scope::HttpReason => plain(0x0F),
            Scope::Number => plain(0x21),
            Scope::Constant | Scope::Escape => plain(0xCA),
            Scope::String | Scope::HeaderValue => plain(0x20),
