/// Write the escape sequence for a style (preceded by a reset).
pub fn write_style(out: &mut dyn Write, style: Style) -> io::Result<()> {
    out.write_all(b"\x1b[0m")?;
    if style.underline {
        out.write_all(b"\x1b[4m")?;
    }
    match style.fg {
        7 => {}
