}

/// A token of highlighted text.
pub type Token<'a> = (Scope, &'a str);

/// Write a sequence of tokens, followed by a final reset.
pub fn write_tokens(out: &mut dyn Write, theme: Theme, tokens: &[Token<'_>]) -> io::Result<()> {
    for (scope, text) in tokens {
        if text.is_empty() {
            continue;
        }
        write_style(out, style_for(theme, *scope))?;
        out.write_all(text.as_bytes())?;
    }
    out.write_all(b"\x1b[0m")
}

