struct JsonRegexes {
    line_comment: Regex,
    block_comment_start: Regex,
    block_comment_end: Regex,
    key: Regex,
    quote: Regex,
    escape: Regex,
    number: Regex,
    boolean: Regex,
    null: Regex,
}

fn json_regexes() -> &'static JsonRegexes {
    static RE: OnceLock<JsonRegexes> = OnceLock::new();
    RE.get_or_init(|| JsonRegexes {
        line_comment: Regex::new(r"//.*").unwrap(),
        block_comment_start: Regex::new(r"/\*").unwrap(),
        block_comment_end: Regex::new(r"\*/").unwrap(),
        key: Regex::new(r#"(")(?i)([^\\"]+)(")\s*?:"#).unwrap(),
        quote: Regex::new(r#"""#).unwrap(),
        escape: Regex::new(r#"\\[tnr"]"#).unwrap(),
        number: Regex::new(r"\d+(?:.\d+)?").unwrap(),
        boolean: Regex::new(r"true|false").unwrap(),
        null: Regex::new(r"null").unwrap(),
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum JsonContext {
    Main,
    BlockComment,
    String,
}

/// Highlighter state for JSON (persists across lines).
pub struct JsonHighlighter {
    context: JsonContext,
}

impl JsonHighlighter {
    pub fn new() -> JsonHighlighter {
        JsonHighlighter { context: JsonContext::Main }
    }

    /// Tokenize a single line (which may end with a newline).
    pub fn tokenize_line<'a>(&mut self, line: &'a str) -> Vec<Token<'a>> {
        let re = json_regexes();
        let mut tokens: Vec<Token<'a>> = Vec::new();
        let mut pos = 0;
        // Pending plain text start for the current context.
        let mut run_start = 0;
        let flush = |tokens: &mut Vec<Token<'a>>, scope: Scope, from: usize, to: usize| {
            if to > from {
                push_token(tokens, scope, &line[from..to]);
            }
        };
        while pos < line.len() {
            match self.context {
                JsonContext::Main => {
                    // Find the earliest match among the rules; ties go to the first rule.
                    let mut best: Option<(usize, usize, usize, Option<regex::Captures>)> = None; // (start, end, rule, caps)
                    let candidates: [(&Regex, usize); 7] = [
                        (&re.line_comment, 0),
                        (&re.block_comment_start, 1),
                        (&re.key, 2),
                        (&re.quote, 3),
                        (&re.number, 4),
                        (&re.boolean, 5),
                        (&re.null, 6),
                    ];
                    for (regex, rule) in candidates {
                        if rule == 2 {
                            if let Some(caps) = regex.captures_at(line, pos) {
                                let m = caps.get(0).unwrap();
                                if best.as_ref().map_or(true, |b| m.start() < b.0) {
                                    best = Some((m.start(), m.end(), rule, Some(caps)));
                                }
                            }
                        } else if let Some(m) = regex.find_at(line, pos) {
                            if best.as_ref().map_or(true, |b| m.start() < b.0) {
                                best = Some((m.start(), m.end(), rule, None));
                            }
                        }
                    }
                    let Some((start, end, rule, caps)) = best else {
                        break;
                    };
                    flush(&mut tokens, Scope::Plain, run_start, start);
                    match rule {
                        0 => push_token(&mut tokens, Scope::Comment, &line[start..end]),
                        1 => {
                            self.context = JsonContext::BlockComment;
                            run_start = start;
                            pos = end;
                            continue;
                        }
                        2 => {
                            let caps = caps.unwrap();
                            let mut cursor = start;
                            for i in 1..=3 {
                                let g = caps.get(i).unwrap();
                                flush(&mut tokens, Scope::Plain, cursor, g.start());
                                push_token(&mut tokens, Scope::JsonKey, &line[g.start()..g.end()]);
                                cursor = g.end();
                            }
                            // the rest of the match (whitespace and colon) is plain
                            run_start = cursor;
                            pos = end.max(cursor);
                            continue;
                        }
                        3 => {
                            self.context = JsonContext::String;
                            run_start = start;
                            pos = end;
                            continue;
                        }
                        4 => push_token(&mut tokens, Scope::Number, &line[start..end]),
                        5 | 6 => push_token(&mut tokens, Scope::Constant, &line[start..end]),
                        _ => unreachable!(),
                    }
                    pos = end;
                    run_start = end;
                }
                JsonContext::BlockComment => match re.block_comment_end.find_at(line, pos) {
                    Some(m) => {
                        flush(&mut tokens, Scope::Comment, run_start, m.end());
                        self.context = JsonContext::Main;
                        pos = m.end();
                        run_start = m.end();
                    }
                    None => {
                        flush(&mut tokens, Scope::Comment, run_start, line.len());
                        return tokens;
                    }
                },
                JsonContext::String => {
                    let quote = re.quote.find_at(line, pos);
                    let escape = re.escape.find_at(line, pos);
                    match (quote, escape) {
                        (None, None) => {
                            flush(&mut tokens, Scope::String, run_start, line.len());
                            return tokens;
                        }
                        (q, e) => {
                            let use_escape = match (q, e) {
                                (Some(q), Some(e)) => e.start() < q.start(),
                                (None, Some(_)) => true,
                                _ => false,
                            };
                            if use_escape {
                                let e = e.unwrap();
                                flush(&mut tokens, Scope::String, run_start, e.start());
                                push_token(&mut tokens, Scope::Escape, &line[e.start()..e.end()]);
                                pos = e.end();
                                run_start = e.end();
                            } else {
                                let q = q.unwrap();
                                flush(&mut tokens, Scope::String, run_start, q.end());
                                self.context = JsonContext::Main;
                                pos = q.end();
                                run_start = q.end();
                            }
                        }
                    }
                }
            }
        }
        let scope = match self.context {
            JsonContext::Main => Scope::Plain,
            JsonContext::BlockComment => Scope::Comment,
            JsonContext::String => Scope::String,
        };
        flush(&mut tokens, scope, run_start, line.len());
        tokens
    }
}

fn push_token<'a>(tokens: &mut Vec<Token<'a>>, scope: Scope, text: &'a str) {
    if text.is_empty() {
        return;
    }
    tokens.push((scope, text));
}

/// Highlight a whole text with the given language and write it out.
pub fn highlight_text(out: &mut dyn Write, theme: Theme, lang: &str, text: &str) -> io::Result<()> {
    let mut tokens: Vec<Token<'_>> = Vec::new();
    match lang {
        "json" => {
            let mut hl = JsonHighlighter::new();
            for line in split_lines(text) {
                tokens.extend(hl.tokenize_line(line));
            }
        }
        "xml" | "html" => {
            let mut hl = crate::highlight_markup::MarkupHighlighter::new(lang == "html");
            for line in split_lines(text) {
                tokens.extend(hl.tokenize_line(line));
            }
        }
        _ => {
            for line in split_lines(text) {
                tokens.push((Scope::Plain, line));
            }
        }
    }
    write_tokens(out, theme, &tokens)
}

/// Split text into lines keeping the line endings.
pub fn split_lines(text: &str) -> Vec<&str> {
    let mut lines = Vec::new();
    let mut start = 0;
    for (i, b) in text.bytes().enumerate() {
        if b == b'\n' {
            lines.push(&text[start..=i]);
            start = i + 1;
        }
    }
    if start < text.len() {
        lines.push(&text[start..]);
    }
    lines
}
