        MarkupHighlighter { state: State::Text, _html: html }
    }

    pub fn tokenize_line<'a>(&mut self, line: &'a str) -> Vec<Token<'a>> {
        let mut tokens: Vec<Token<'a>> = Vec::new();
        let bytes = line.as_bytes();
        let mut pos = 0;
        let mut run_start = 0;
        let push = |tokens: &mut Vec<Token<'a>>, scope: Scope, from: usize, to: usize| {
            if to > from {
                tokens.push((scope, &line[from..to]));
            }
        };
        while pos < bytes.len() {
            match self.state {
                State::Text => {
                    if line[pos..].starts_with("<!--") {
                        push(&mut tokens, Scope::Plain, run_start, pos);
                        push(&mut tokens, Scope::Comment, pos, pos + 4);
                        pos += 4;
                        run_start = pos;
                        self.state = State::Comment;
                    } else if line[pos..].starts_with("<!") {
                        push(&mut tokens, Scope::Plain, run_start, pos);
                        push(&mut tokens, Scope::Doctype, pos, pos + 2);
                        pos += 2;
                        run_start = pos;
                        self.state = State::Doctype;
                    } else if bytes[pos] == b'<' {
                        push(&mut tokens, Scope::Plain, run_start, pos);
                        let mut end = pos + 1;
                        if end < bytes.len() && (bytes[end] == b'/' || bytes[end] == b'?') {
                            end += 1;
                        }
                        push(&mut tokens, Scope::Plain, pos, end);
                        pos = end;
                        // tag name
                        let name_end = scan_name(line, pos);
                        push(&mut tokens, Scope::TagName, pos, name_end);
                        pos = name_end;
                        run_start = pos;
                        self.state = State::Tag;
                    } else if bytes[pos] == b'&' {
                        if let Some(semi) = line[pos..].find(';') {
                            let name = &line[pos + 1..pos + semi];
                            if !name.is_empty() && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '#') {
                                push(&mut tokens, Scope::Plain, run_start, pos);
                                push(&mut tokens, Scope::Constant, pos, pos + 1);
                                push(&mut tokens, Scope::Constant, pos + 1, pos + semi);
                                push(&mut tokens, Scope::Constant, pos + semi, pos + semi + 1);
                                pos += semi + 1;
                                run_start = pos;
                                continue;
                            }
                        }
                        pos += 1;
                    } else {
                        pos += next_char_len(line, pos);
                    }
                }
                State::Comment => match line[pos..].find("-->") {
                    Some(i) => {
                        push(&mut tokens, Scope::Comment, run_start, pos + i);
                        push(&mut tokens, Scope::Comment, pos + i, pos + i + 3);
                        pos += i + 3;
                        run_start = pos;
                        self.state = State::Text;
                    }
                    None => {
                        push(&mut tokens, Scope::Comment, run_start, line.len());
                        return tokens;
                    }
                },
                State::Doctype => match line[pos..].find('>') {
                    Some(i) => {
                        push(&mut tokens, Scope::Doctype, run_start, pos + i + 1);
                        pos += i + 1;
                        run_start = pos;
                        self.state = State::Text;
                    }
                    None => {
                        push(&mut tokens, Scope::Doctype, run_start, line.len());
                        return tokens;
                    }
                },
                State::Tag => {
                    let b = bytes[pos];
                    if b == b'>' || line[pos..].starts_with("/>") || line[pos..].starts_with("?>") {
                        push(&mut tokens, Scope::Plain, run_start, pos);
                        let end = if b == b'>' { pos + 1 } else { pos + 2 };
                        push(&mut tokens, Scope::Plain, pos, end);
                        pos = end;
                        run_start = pos;
                        self.state = State::Text;
                    } else if b == b'"' || b == b'\'' {
                        push(&mut tokens, Scope::Plain, run_start, pos);
                        push(&mut tokens, Scope::String, pos, pos + 1);
                        pos += 1;
                        run_start = pos;
                        self.state = State::Quoted(b);
                    } else if b.is_ascii_alphabetic() || b == b'_' || b == b':' {
                        push(&mut tokens, Scope::Plain, run_start, pos);
                        let end = scan_name(line, pos);
                        push(&mut tokens, Scope::AttributeName, pos, end);
                        pos = end;
                        run_start = pos;
                    } else {
                        pos += next_char_len(line, pos);
                    }
                }
                State::Quoted(q) => match line[pos..].find(q as char) {
                    Some(i) => {
                        push(&mut tokens, Scope::String, run_start, pos + i);
                        push(&mut tokens, Scope::String, pos + i, pos + i + 1);
                        pos += i + 1;
                        run_start = pos;
                        self.state = State::Tag;
                    }
                    None => {
                        push(&mut tokens, Scope::String, run_start, line.len());
                        return tokens;
                    }
                },
            }
        }
        let scope = match self.state {
            State::Text | State::Tag => Scope::Plain,
            State::Comment => Scope::Comment,
            State::Quoted(_) => Scope::String,
            State::Doctype => Scope::Doctype,
        };
        push(&mut tokens, scope, run_start, line.len());
        tokens
    }
}

fn scan_name(line: &str, start: usize) -> usize {
    let bytes = line.as_bytes();
    let mut end = start;
    while end < bytes.len() {
        let b = bytes[end];
        if b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b':' | b'.') || b >= 0x80 {
            end += 1;
        } else {
            break;
        }
    }
    end
}

fn next_char_len(line: &str, pos: usize) -> usize {
    line[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1)
}
