//! Output of requests and responses.

use std::fs::File;
use std::io::{self, Read, Write};
use std::time::Duration;

use anyhow::Result;

use crate::args::{Pretty, Theme};
use crate::decoder::Encoding;
use crate::headers::HeaderMap;
use crate::highlight::{self, Scope, Token};
use crate::http::{Request, Response, Version};

/// Which parts of the exchange to print.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Print {
    pub request_headers: bool,
    pub request_body: bool,
    pub response_headers: bool,
    pub response_body: bool,
    pub response_meta: bool,
}

impl Print {
    pub fn from_format(s: &str) -> Print {
        Print {
            request_headers: s.contains('H'),
            request_body: s.contains('B'),
            response_headers: s.contains('h'),
            response_body: s.contains('b'),
            response_meta: s.contains('m'),
        }
    }

    pub fn new(verbose: u8, headers: bool, body: bool, meta: bool, quiet: bool, offline: bool, is_terminal: bool) -> Print {
        if verbose > 0 {
            Print {
                request_headers: true,
                request_body: true,
                response_headers: true,
                response_body: true,
                response_meta: verbose > 1,
            }
        } else if quiet {
            Print::none()
        } else if offline {
            Print { request_headers: true, request_body: true, response_headers: false, response_body: false, response_meta: false }
        } else if headers {
            Print { request_headers: false, request_body: false, response_headers: true, response_body: false, response_meta: false }
        } else if body || !is_terminal {
            Print { request_headers: false, request_body: false, response_headers: false, response_body: true, response_meta: false }
        } else if meta {
            Print { request_headers: false, request_body: false, response_headers: false, response_body: false, response_meta: true }
        } else {
            Print { request_headers: false, request_body: false, response_headers: true, response_body: true, response_meta: false }
        }
    }

    pub fn none() -> Print {
        Print { request_headers: false, request_body: false, response_headers: false, response_body: false, response_meta: false }
    }
}

/// Where the output goes.
pub enum Buffer {
    Stdout(io::Stdout),
    Stderr(io::Stderr),
    File(File),
    /// stdout, but not a terminal
    Redirect(io::Stdout),
}

impl Buffer {
    pub fn new(download: bool, output: Option<&std::path::Path>, is_stdout_tty: bool) -> io::Result<Buffer> {
        Ok(if download {
            Buffer::Stderr(io::stderr())
        } else if let Some(output) = output {
            Buffer::File(File::create(output)?)
        } else if is_stdout_tty {
            Buffer::Stdout(io::stdout())
        } else {
            Buffer::Redirect(io::stdout())
        })
    }

    pub fn is_terminal(&self) -> bool {
        match self {
            Buffer::Stdout(_) => true,
            Buffer::Stderr(_) => crate::utils::stderr_is_terminal(),
            Buffer::File(_) => false,
            Buffer::Redirect(_) => false,
        }
    }

    pub fn is_redirect(&self) -> bool {
        matches!(self, Buffer::Redirect(_))
    }
}

impl Write for Buffer {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self {
            Buffer::Stdout(s) | Buffer::Redirect(s) => s.write(buf),
            Buffer::Stderr(s) => s.write(buf),
            Buffer::File(f) => f.write(buf),
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        match self {
            Buffer::Stdout(s) | Buffer::Redirect(s) => s.flush(),
            Buffer::Stderr(s) => s.flush(),
            Buffer::File(f) => f.flush(),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ContentType {
    Json,
    Html,
    Xml,
    JavaScript,
    Css,
    Text,
    UrlencodedForm,
    Multipart,
    EventStream,
    Unknown,
}

pub fn content_type_from(ct: &str) -> ContentType {
    if ct.contains("json") {
        ContentType::Json
    } else if ct.contains("html") {
        ContentType::Html
    } else if ct.contains("xml") {
        ContentType::Xml
    } else if ct.contains("multipart") {
        ContentType::Multipart
    } else if ct.contains("x-www-form-urlencoded") {
        ContentType::UrlencodedForm
    } else if ct.contains("javascript") {
        ContentType::JavaScript
    } else if ct.contains("css") {
        ContentType::Css
    } else if ct.contains("event-stream") {
        ContentType::EventStream
    } else if ct.contains("text") {
        ContentType::Text
    } else {
        ContentType::Unknown
    }
}

pub fn get_content_type(headers: &HeaderMap) -> ContentType {
    headers
        .get_str("content-type")
        .map(content_type_from)
        .unwrap_or(ContentType::Unknown)
}

pub const BINARY_SUPPRESSOR: &str = concat!(
    "+-----------------------------------------+\n",
    "| NOTE: binary data not shown in terminal |\n",
    "+-----------------------------------------+\n"
);

pub struct Printer {
    pub indent_json: Option<usize>,
    pub color: bool,
    pub theme: Theme,
    pub sort_headers: bool,
    pub stream: bool,
    pub buffer: Buffer,
    pub response_charset: Option<Encoding>,
    pub response_mime: Option<String>,
}

impl Printer {
    pub fn new(
        pretty: Pretty,
        theme: Theme,
        stream: bool,
        buffer: Buffer,
        format_options: crate::args::FormatOptions,
    ) -> Printer {
        let format = format_options.json_format.unwrap_or(pretty.format());
        let indent = format_options.json_indent.unwrap_or(4);
        Printer {
            indent_json: if format { Some(indent) } else { None },
            color: pretty.color(),
            theme,
            sort_headers: format_options.headers_sort.unwrap_or(pretty.format()),
            stream,
            buffer,
            response_charset: None,
            response_mime: None,
        }
    }

    fn write_plain(&mut self, text: &str) -> io::Result<()> {
        self.buffer.write_all(text.as_bytes())
    }

    fn write_tokens(&mut self, tokens: &[Token<'_>]) -> io::Result<()> {
        highlight::write_tokens(&mut self.buffer, self.theme, tokens)
    }

    /// Print a block of tokens: colored or plain.
    fn print_tokens_or_plain(&mut self, tokens: Vec<Token<'_>>) -> io::Result<()> {
        if self.color {
            self.write_tokens(&tokens)
        } else {
            for (_, text) in tokens {
                self.buffer.write_all(text.as_bytes())?;
            }
            Ok(())
        }
    }

    fn header_tokens<'a>(&self, headers: &'a HeaderMap, storage: &'a mut Vec<(String, Vec<u8>)>) -> Vec<Token<'a>> {
        let mut entries: Vec<(String, Vec<u8>)> = headers
            .iter()
            .map(|(name, value)| (name.titled(), value.to_vec()))
            .collect();
        if self.sort_headers {
            entries.sort_by(|a, b| a.0.cmp(&b.0));
        }
        *storage = entries;
        let mut decoded: Vec<Token<'a>> = Vec::new();
        for (name, value) in storage.iter() {
            decoded.push((Scope::HeaderName, name.as_str()));
            decoded.push((Scope::HttpSeparator, ":"));
            decoded.push((Scope::Plain, " "));
            // Values are stored in the storage as raw bytes; display handled below.
            let _ = value;
            decoded.push((Scope::Plain, "\n"));
        }
        decoded
    }

    /// Render headers as text (used for both colored and plain output).
    fn headers_to_tokens(&self, headers: &HeaderMap) -> (Vec<(Scope, String)>, ()) {
        let mut entries: Vec<(String, Vec<u8>)> = headers
            .iter()
            .map(|(name, value)| (name.titled(), value.to_vec()))
            .collect();
        if self.sort_headers {
            entries.sort_by(|a, b| a.0.cmp(&b.0));
        }
        let mut tokens: Vec<(Scope, String)> = Vec::new();
        for (name, value) in entries {
            tokens.push((Scope::HeaderName, name));
            tokens.push((Scope::HttpSeparator, ":".to_string()));
            tokens.push((Scope::Plain, " ".to_string()));
            if value.is_ascii() {
                tokens.push((Scope::HeaderValue, String::from_utf8_lossy(&value).into_owned()));
            } else {
                let latin1: String = value.iter().map(|&b| b as char).collect();
                tokens.push((Scope::Error, latin1));
                if let Ok(utf8) = std::str::from_utf8(&value) {
                    tokens.push((Scope::Plain, " (UTF-8: ".to_string()));
                    tokens.push((Scope::HeaderValue, utf8.to_string()));
                    tokens.push((Scope::Plain, ")".to_string()));
                }
            }
            tokens.push((Scope::Plain, "\n".to_string()));
        }
        (tokens, ())
    }

    fn print_owned_tokens(&mut self, tokens: Vec<(Scope, String)>) -> io::Result<()> {
        let borrowed: Vec<Token<'_>> = tokens.iter().map(|(s, t)| (*s, t.as_str())).collect();
        self.print_tokens_or_plain(borrowed)
    }

    pub fn print_request_headers(&mut self, request: &Request, headers: &HeaderMap) -> io::Result<()> {
        let version = match request.version {
            Version::Http10 => "1.0",
            Version::Http11 => "1.1",
            Version::Http2 => "2.0",
        };
        let mut tokens: Vec<(Scope, String)> = vec![
            (Scope::HttpMethod, request.method.clone()),
            (Scope::Plain, " ".to_string()),
            (Scope::HttpUrl, request.path_and_query()),
            (Scope::Plain, " ".to_string()),
            (Scope::HttpKeyword, "HTTP".to_string()),
            (Scope::HttpSeparator, "/".to_string()),
            (Scope::Number, version.to_string()),
            (Scope::Plain, "\n".to_string()),
        ];
        let (header_tokens, _) = self.headers_to_tokens(headers);
        if request.version == Version::Http2 {
            // HTTP/2 shows lowercase header names
            tokens.extend(header_tokens.into_iter().map(|(s, t)| {
                if s == Scope::HeaderName {
                    (s, t.to_ascii_lowercase())
                } else {
                    (s, t)
                }
            }));
        } else {
            tokens.extend(header_tokens);
        }
        self.print_owned_tokens(tokens)?;
        self.write_plain("\n")
    }

    pub fn print_response_headers(&mut self, response: &Response) -> io::Result<()> {
        let version = match response.version {
            Version::Http10 => "1.0",
            Version::Http11 => "1.1",
            Version::Http2 => "2.0",
        };
        let mut tokens: Vec<(Scope, String)> = vec![
            (Scope::HttpKeyword, "HTTP".to_string()),
            (Scope::HttpSeparator, "/".to_string()),
            (Scope::Number, version.to_string()),
            (Scope::Plain, " ".to_string()),
            (Scope::Number, response.status.to_string()),
            (Scope::Plain, " ".to_string()),
            (Scope::HttpReason, response.reason.clone()),
            (Scope::Plain, "\n".to_string()),
        ];
        let (header_tokens, _) = self.headers_to_tokens(&response.headers);
        tokens.extend(header_tokens);
        self.print_owned_tokens(tokens)?;
        self.write_plain("\n")
    }

    /// Print a separator between messages.
    pub fn print_separator(&mut self) -> io::Result<()> {
        self.write_plain("\n")
    }

    /// Format JSON if possible (returns None when the text is not valid JSON).
    fn format_json(&self, text: &str) -> Option<String> {
        let indent = self.indent_json?;
        let value: serde_json::Value = serde_json::from_str(text).ok()?;
        let mut out = Vec::new();
        let indent_str = " ".repeat(indent);
        let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
        let mut ser = serde_json::Serializer::with_formatter(&mut out, formatter);
        serde::Serialize::serialize(&value, &mut ser).ok()?;
        let mut s = String::from_utf8(out).ok()?;
        s.push('\n');
        Some(s)
    }

    fn valid_json(text: &str) -> bool {
        serde_json::from_str::<serde_json::de::IgnoredAny>(text).is_ok()
    }

    /// Print a syntax highlighted (or plain) text body.
    fn print_syntax_text(&mut self, text: &str, lang: &str) -> io::Result<()> {
        if self.color {
            highlight::highlight_text(&mut self.buffer, self.theme, lang, text)
        } else {
            self.write_plain(text)
        }
    }

    fn print_json_text(&mut self, text: &str, check_valid: bool) -> io::Result<()> {
        if self.indent_json.is_none() {
            return self.print_syntax_text(text, "json");
        }
        if check_valid && !Self::valid_json(text) {
            return self.print_syntax_text(text, "json");
        }
        match self.format_json(text) {
            Some(mut formatted) => {
                formatted.push('\n');
                self.print_syntax_text(&formatted, "json")
            }
            None => self.print_syntax_text(text, "json"),
        }
    }

    /// Print body text according to its content type.
    pub fn print_body_text(&mut self, content_type: ContentType, text: &str) -> io::Result<()> {
        match content_type {
            ContentType::Json => self.print_json_text(text, true),
            ContentType::Html => self.print_syntax_text(text, "html"),
            ContentType::Xml => self.print_syntax_text(text, "xml"),
            ContentType::JavaScript => {
                if Self::valid_json(text) {
                    self.print_json_text(text, false)
                } else {
                    self.print_syntax_text(text, "js")
                }
            }
            ContentType::Css => self.print_syntax_text(text, "css"),
            ContentType::Text => {
                if Self::valid_json(text) {
                    self.print_json_text(text, false)
                } else {
                    self.write_plain(text)
                }
            }
            ContentType::UrlencodedForm | ContentType::Multipart | ContentType::EventStream | ContentType::Unknown => {
                self.write_plain(text)
            }
        }
    }

    /// Print the request body.
    pub fn print_request_body(&mut self, headers: &HeaderMap, body: &[u8], printable: bool) -> io::Result<()> {
        let content_type = get_content_type(headers);
        if !printable {
            // Streaming bodies (files, multipart) are not printed from memory here.
            return Ok(());
        }
        if body.contains(&0) {
            self.write_plain(BINARY_SUPPRESSOR)?;
        } else {
            let text = String::from_utf8_lossy(body);
            self.print_body_text(content_type, &text)?;
        }
        self.write_plain("\n")?;
        self.write_plain("\n")
    }

    /// Decode body bytes to text with the given encoding.
    fn decode_body(&self, bytes: &[u8], content_type_header: Option<&str>, content_type: ContentType) -> String {
        let encoding = self.response_charset.or_else(|| {
            content_type_header
                .and_then(|ct| crate::decoder::charset_from_content_type(ct))
                .and_then(|label| Encoding::for_label(&label))
        });
        crate::decoder::decode(bytes, encoding, content_type == ContentType::Json)
    }

    /// Print the response body, buffering or streaming it.
    pub fn print_response_body(&mut self, response: &mut Response) -> Result<()> {
        let content_type_header = self
            .response_mime
            .clone()
            .or_else(|| response.headers.get_str("content-type").map(|s| s.to_string()));
        let content_type = content_type_header
            .as_deref()
            .map(content_type_from)
            .unwrap_or(ContentType::Unknown);

        let is_terminal = self.buffer.is_terminal();
        let formatting = self.indent_json.is_some() || self.color;

        if self.stream {
            // Stream the body as-is, chunk by chunk, unless it needs formatting.
            let needs_buffering = formatting && matches!(content_type, ContentType::Json | ContentType::JavaScript | ContentType::Text);
            if !needs_buffering {
                let mut buf = [0u8; 8192];
                let mut first = true;
                let mut saw_binary = false;
                loop {
                    let n = response.body.read(&mut buf)?;
                    if n == 0 {
                        break;
                    }
                    let chunk = &buf[..n];
                    if is_terminal && first && chunk.contains(&0) {
                        saw_binary = true;
                    }
                    first = false;
                    if saw_binary {
                        continue;
                    }
                    if self.color && content_type_is_highlightable(content_type) {
                        let text = String::from_utf8_lossy(chunk);
                        let lang = lang_for(content_type);
                        highlight::highlight_text(&mut self.buffer, self.theme, lang, &text)?;
                    } else {
                        self.buffer.write_all(chunk)?;
                    }
                    self.buffer.flush()?;
                }
                if saw_binary {
                    self.write_plain(BINARY_SUPPRESSOR)?;
                    self.write_plain("\n")?;
                }
                return Ok(());
            }
        }

        let bytes = response.read_body()?;
        if !formatting && !is_terminal && self.response_charset.is_none() {
            // Raw passthrough
            self.buffer.write_all(&bytes)?;
            return Ok(());
        }
        let text = self.decode_body(&bytes, content_type_header.as_deref(), content_type);
        if is_terminal && text.contains('\0') {
            self.write_plain(BINARY_SUPPRESSOR)?;
            self.write_plain("\n")?;
            return Ok(());
        }
        if !formatting {
            self.write_plain(&text)?;
            return Ok(());
        }
        self.print_body_text(content_type, &text)?;
        Ok(())
    }

    pub fn print_response_meta(&mut self, elapsed: Duration, remote_addr: Option<std::net::SocketAddr>) -> io::Result<()> {
        let mut tokens: Vec<(Scope, String)> = vec![
            (Scope::HeaderName, "Elapsed time".to_string()),
            (Scope::HttpSeparator, ":".to_string()),
            (Scope::Plain, " ".to_string()),
            (Scope::HeaderValue, format!("{:.5}s", elapsed.as_secs_f64())),
            (Scope::Plain, "\n".to_string()),
        ];
        if let Some(addr) = remote_addr {
            tokens.push((Scope::HeaderName, "Remote address".to_string()));
            tokens.push((Scope::HttpSeparator, ":".to_string()));
            tokens.push((Scope::Plain, " ".to_string()));
            tokens.push((Scope::HeaderValue, addr.to_string()));
            tokens.push((Scope::Plain, "\n".to_string()));
        }
        // Meta is never colored
        for (_, t) in tokens {
            self.write_plain(&t)?;
        }
        self.write_plain("\n")
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.buffer.flush()
    }
}

fn content_type_is_highlightable(ct: ContentType) -> bool {
    matches!(ct, ContentType::Json | ContentType::Html | ContentType::Xml | ContentType::JavaScript | ContentType::Css)
}

fn lang_for(ct: ContentType) -> &'static str {
    match ct {
        ContentType::Json => "json",
        ContentType::Html => "html",
        ContentType::Xml => "xml",
        ContentType::JavaScript => "js",
        ContentType::Css => "css",
        _ => "text",
    }
}
