/// Which parts of the exchange to print.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Print {
    pub request_headers: bool,
    pub request_body: bool,
    pub response_headers: bool,
    pub response_body: bool,
    pub response_meta: bool,
}

impl Print {
    pub fn from_format(s: &str) -> Print {
        Print {
            request_headers: s.contains('H'),
            request_body: s.contains('B'),
            response_headers: s.contains('h'),
            response_body: s.contains('b'),
            response_meta: s.contains('m'),
        }
    }

    pub fn new(verbose: u8, headers: bool, body: bool, meta: bool, quiet: bool, offline: bool, is_terminal: bool) -> Print {
        if verbose > 0 {
            Print {
                request_headers: true,
                request_body: true,
                response_headers: true,
                response_body: true,
                response_meta: verbose > 1,
            }
        } else if quiet {
            Print::none()
        } else if offline {
            Print { request_headers: true, request_body: true, response_headers: false, response_body: false, response_meta: false }
        } else if headers {
            Print { request_headers: false, request_body: false, response_headers: true, response_body: false, response_meta: false }
        } else if body || !is_terminal {
            Print { request_headers: false, request_body: false, response_headers: false, response_body: true, response_meta: false }
        } else if meta {
            Print { request_headers: false, request_body: false, response_headers: false, response_body: false, response_meta: true }
        } else {
            Print { request_headers: false, request_body: false, response_headers: true, response_body: true, response_meta: false }
        }
    }

    pub fn none() -> Print {
        Print { request_headers: false, request_body: false, response_headers: false, response_body: false, response_meta: false }
    }
}

/// Where the output goes.
pub enum Buffer {
    Stdout(io::Stdout),
    Stderr(io::Stderr),
    File(File),
    /// stdout, but not a terminal
    Redirect(io::Stdout),
}

impl Buffer {
    pub fn new(download: bool, output: Option<&std::path::Path>, is_stdout_tty: bool) -> io::Result<Buffer> {
        Ok(if download {
            Buffer::Stderr(io::stderr())
        } else if let Some(output) = output {
            Buffer::File(File::create(output)?)
        } else if is_stdout_tty {
            Buffer::Stdout(io::stdout())
        } else {
            Buffer::Redirect(io::stdout())
        })
    }

    pub fn is_terminal(&self) -> bool {
        match self {
            Buffer::Stdout(_) => true,
            Buffer::Stderr(_) => crate::utils::stderr_is_terminal(),
            Buffer::File(_) => false,
            Buffer::Redirect(_) => false,
        }
    }

    pub fn is_redirect(&self) -> bool {
        matches!(self, Buffer::Redirect(_))
    }
}

impl Write for Buffer {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self {
            Buffer::Stdout(s) | Buffer::Redirect(s) => s.write(buf),
            Buffer::Stderr(s) => s.write(buf),
            Buffer::File(f) => f.write(buf),
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        match self {
            Buffer::Stdout(s) | Buffer::Redirect(s) => s.flush(),
            Buffer::Stderr(s) => s.flush(),
            Buffer::File(f) => f.flush(),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ContentType {
    Json,
    Html,
    Xml,
    JavaScript,
    Css,
    Text,
    UrlencodedForm,
    Multipart,
    EventStream,
    Unknown,
}

pub fn content_type_from(ct: &str) -> ContentType {
    if ct.contains("json") {
        ContentType::Json
    } else if ct.contains("html") {
        ContentType::Html
    } else if ct.contains("xml") {
        ContentType::Xml
    } else if ct.contains("multipart") {
        ContentType::Multipart
    } else if ct.contains("x-www-form-urlencoded") {
        ContentType::UrlencodedForm
    } else if ct.contains("javascript") {
        ContentType::JavaScript
    } else if ct.contains("css") {
        ContentType::Css
    } else if ct.contains("event-stream") {
        ContentType::EventStream
    } else if ct.contains("text") {
        ContentType::Text
    } else {
        ContentType::Unknown
    }
}

