            (Scope::HttpKeyword, "HTTP".to_string()),
            (Scope::HttpSeparator, "/".to_string()),
            (Scope::Number, version.to_string()),
            (Scope::Plain, " ".to_string()),
            (Scope::Number, response.status.to_string()),
            (Scope::Plain, " ".to_string()),
            (Scope::HttpReason, response.reason.clone()),
            (Scope::Plain, "\n".to_string()),
        ];
        let (header_tokens, _) = self.headers_to_tokens(&response.headers);
        tokens.extend(header_tokens);
        self.print_owned_tokens(tokens)?;
        self.write_plain("\n")
    }

    /// Print a separator between messages.
    pub fn print_separator(&mut self) -> io::Result<()> {
        self.write_plain("\n")
    }

    /// Format JSON if possible (returns None when the text is not valid JSON).
    fn format_json(&self, text: &str) -> Option<String> {
        let indent = self.indent_json?;
        let value: serde_json::Value = serde_json::from_str(text).ok()?;
        let mut out = Vec::new();
        let indent_str = " ".repeat(indent);
        let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
        let mut ser = serde_json::Serializer::with_formatter(&mut out, formatter);
        serde::Serialize::serialize(&value, &mut ser).ok()?;
        let mut s = String::from_utf8(out).ok()?;
        s.push('\n');
        Some(s)
    }

    fn valid_json(text: &str) -> bool {
        serde_json::from_str::<serde_json::de::IgnoredAny>(text).is_ok()
    }

    /// Print a syntax highlighted (or plain) text body.
    fn print_syntax_text(&mut self, text: &str, lang: &str) -> io::Result<()> {
        if self.color {
            highlight::highlight_text(&mut self.buffer, self.theme, lang, text)
        } else {
            self.write_plain(text)
        }
    }

    fn print_json_text(&mut self, text: &str, check_valid: bool) -> io::Result<()> {
        if self.indent_json.is_none() {
            return self.print_syntax_text(text, "json");
        }
        if check_valid && !Self::valid_json(text) {
            return self.print_syntax_text(text, "json");
        }
        match self.format_json(text) {
            Some(mut formatted) => {
                formatted.push('\n');
                self.print_syntax_text(&formatted, "json")
            }
            None => self.print_syntax_text(text, "json"),
        }
    }

    /// Print body text according to its content type.
    pub fn print_body_text(&mut self, content_type: ContentType, text: &str) -> io::Result<()> {
        match content_type {
            ContentType::Json => self.print_json_text(text, true),
            ContentType::Html => self.print_syntax_text(text, "html"),
            ContentType::Xml => self.print_syntax_text(text, "xml"),
            ContentType::JavaScript => {
                if Self::valid_json(text) {
                    self.print_json_text(text, false)
                } else {
                    self.print_syntax_text(text, "js")
                }
            }
            ContentType::Css => self.print_syntax_text(text, "css"),
            ContentType::Text => {
                if Self::valid_json(text) {
                    self.print_json_text(text, false)
                } else {
                    self.write_plain(text)
                }
            }
            ContentType::UrlencodedForm | ContentType::Multipart | ContentType::EventStream | ContentType::Unknown => {
                self.write_plain(text)
            }
        }
    }

    /// Print the request body.
    pub fn print_request_body(&mut self, headers: &HeaderMap, body: &[u8], printable: bool) -> io::Result<()> {
        let content_type = get_content_type(headers);
        if !printable {
            // Streaming bodies (files, multipart) are not printed from memory here.
            return Ok(());
        }
        if body.contains(&0) {
            self.write_plain(BINARY_SUPPRESSOR)?;
        } else {
            let text = String::from_utf8_lossy(body);
            self.print_body_text(content_type, &text)?;
        }
        self.write_plain("\n")?;
        self.write_plain("\n")
    }

    /// Decode body bytes to text with the given encoding.
    fn decode_body(&self, bytes: &[u8], content_type_header: Option<&str>, content_type: ContentType) -> String {
        let encoding = self.response_charset.or_else(|| {
            content_type_header
                .and_then(|ct| crate::decoder::charset_from_content_type(ct))
                .and_then(|label| Encoding::for_label(&label))
        });
        crate::decoder::decode(bytes, encoding, content_type == ContentType::Json)
    }

    /// Print the response body, buffering or streaming it.
    pub fn print_response_body(&mut self, response: &mut Response) -> Result<()> {
        let content_type_header = self
            .response_mime
            .clone()
            .or_else(|| response.headers.get_str("content-type").map(|s| s.to_string()));
        let content_type = content_type_header
            .as_deref()
            .map(content_type_from)
            .unwrap_or(ContentType::Unknown);

        let is_terminal = self.buffer.is_terminal();
        let formatting = self.indent_json.is_some() || self.color;

        if self.stream {
            // Stream the body as-is, chunk by chunk, unless it needs formatting.
            let needs_buffering = formatting && matches!(content_type, ContentType::Json | ContentType::JavaScript | ContentType::Text);
            if !needs_buffering {
                let mut buf = [0u8; 8192];
                let mut first = true;
                let mut saw_binary = false;
                loop {
                    let n = response.body.read(&mut buf)?;
                    if n == 0 {
                        break;
                    }
                    let chunk = &buf[..n];
                    if is_terminal && first && chunk.contains(&0) {
                        saw_binary = true;
                    }
                    first = false;
                    if saw_binary {
                        continue;
                    }
                    if self.color && content_type_is_highlightable(content_type) {
                        let text = String::from_utf8_lossy(chunk);
                        let lang = lang_for(content_type);
                        highlight::highlight_text(&mut self.buffer, self.theme, lang, &text)?;
                    } else {
                        self.buffer.write_all(chunk)?;
                    }
                    self.buffer.flush()?;
                }
                if saw_binary {
                    self.write_plain(BINARY_SUPPRESSOR)?;
                    self.write_plain("\n")?;
                }
                return Ok(());
            }
        }

        let bytes = response.read_body()?;
        if !formatting && !is_terminal && self.response_charset.is_none() {
            // Raw passthrough
            self.buffer.write_all(&bytes)?;
            return Ok(());
        }
        let text = self.decode_body(&bytes, content_type_header.as_deref(), content_type);
        if is_terminal && text.contains('\0') {
            self.write_plain(BINARY_SUPPRESSOR)?;
            self.write_plain("\n")?;
            return Ok(());
        }
        if !formatting {
            self.write_plain(&text)?;
            return Ok(());
        }
        self.print_body_text(content_type, &text)?;
        Ok(())
    }

    pub fn print_response_meta(&mut self, elapsed: Duration, remote_addr: Option<std::net::SocketAddr>) -> io::Result<()> {
        let mut tokens: Vec<(Scope, String)> = vec![
            (Scope::HeaderName, "Elapsed time".to_string()),
            (Scope::HttpSeparator, ":".to_string()),
            (Scope::Plain, " ".to_string()),
            (Scope::HeaderValue, format!("{:.5}s", elapsed.as_secs_f64())),
            (Scope::Plain, "\n".to_string()),
        ];
        if let Some(addr) = remote_addr {
            tokens.push((Scope::HeaderName, "Remote address".to_string()));
            tokens.push((Scope::HttpSeparator, ":".to_string()));
            tokens.push((Scope::Plain, " ".to_string()));
            tokens.push((Scope::HeaderValue, addr.to_string()));
            tokens.push((Scope::Plain, "\n".to_string()));
        }
        // Meta is never colored
        for (_, t) in tokens {
            self.write_plain(&t)?;
        }
        self.write_plain("\n")
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.buffer.flush()
    }
}

fn content_type_is_highlightable(ct: ContentType) -> bool {
    matches!(ct, ContentType::Json | ContentType::Html | ContentType::Xml | ContentType::JavaScript | ContentType::Css)
}

fn lang_for(ct: ContentType) -> &'static str {
    match ct {
        ContentType::Json => "json",
        ContentType::Html => "html",
        ContentType::Xml => "xml",
        ContentType::JavaScript => "js",
        ContentType::Css => "css",
        _ => "text",
    }
}
EOF
