}

fn decode_utf16(bytes: &[u8], little_endian: bool) -> String {
    let mut units = Vec::with_capacity(bytes.len() / 2);
    let mut chunks = bytes.chunks_exact(2);
    for c in &mut chunks {
        units.push(if little_endian { u16::from_le_bytes([c[0], c[1]]) } else { u16::from_be_bytes([c[0], c[1]]) });
    }
    let mut s: String = char::decode_utf16(units.iter().copied())
        .map(|r| r.unwrap_or('\u{FFFD}'))
        .collect();
    if !chunks.remainder().is_empty() {
        s.push('\u{FFFD}');
    }
    s
}

/// Decode with the explicit encoding (BOM aware), or sniff when none is given.
pub fn decode(bytes: &[u8], encoding: Option<Encoding>, _is_json: bool) -> String {
    // BOM sniffing takes precedence like in the WHATWG `decode` algorithm.
    if bytes.starts_with(&[0xEF, 0xBB, 0xBF]) {
        return String::from_utf8_lossy(&bytes[3..]).into_owned();
    }
    if bytes.starts_with(&[0xFF, 0xFE]) {
        return decode_utf16(&bytes[2..], true);
    }
    if bytes.starts_with(&[0xFE, 0xFF]) {
        return decode_utf16(&bytes[2..], false);
    }
    match encoding {
        Some(Encoding::Utf8) => String::from_utf8_lossy(bytes).into_owned(),
        Some(Encoding::Utf16Le) => decode_utf16(bytes, true),
        Some(Encoding::Utf16Be) => decode_utf16(bytes, false),
        Some(Encoding::Windows1252) => decode_windows_1252(bytes),
        Some(Encoding::Latin2) => bytes
            .iter()
            .map(|&b| if b < 0xA0 { b as char } else { LATIN2_HIGH[(b - 0xA0) as usize] })
            .collect(),
        Some(Encoding::Windows1251) => decode_single_byte(bytes, &WINDOWS_1251_HIGH),
        Some(Encoding::Koi8R) => decode_single_byte(bytes, &KOI8R_HIGH),
        Some(Encoding::Replacement) => {
            if bytes.is_empty() {
                String::new()
            } else {
                "\u{FFFD}".to_string()
            }
        }
        None => match std::str::from_utf8(bytes) {
            Ok(s) => s.to_string(),
            Err(_) => decode_windows_1252(bytes),
        },
    }
}
