/// Error carrying an explicit exit code.
#[derive(Debug)]
pub struct ExitCode(pub i32);

fn bin_name() -> String {
    std::env::args_os()
        .next()
        .map(|a| std::path::PathBuf::from(a))
        .and_then(|p| p.file_name().map(|f| f.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "xh".to_string())
}

fn main() {
    let bin = bin_name();
    let code = match run(&bin) {
        Ok(code) => code,
        Err(err) => {
            if let Some(exit) = err.downcast_ref::<args::ExitError>() {
                // clap style error: already formatted (usage included)
                let _ = std::io::stdout().flush();
                eprint!("{}", exit.message);
                if !exit.message.ends_with('\n') {
                    eprintln!();
                }
                exit.code
            } else if let Some(ExitCode(code)) = err.downcast_ref::<ExitCode>() {
