fn is_timeout(err: &anyhow::Error) -> bool {
    err.chain().any(|e| e.downcast_ref::<http::client::TimedOut>().is_some())
}

fn warn(bin: &str, quiet: u8, msg: &str) {
    if quiet < 2 {
        let _ = std::io::stdout().flush();
        eprintln!("{}: warning: {}", bin, msg);
    }
}

fn run(bin: &str) -> Result<i32> {
    let mut argv: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let default_options = config::default_options();
    if !default_options.is_empty() {
        let mut merged = vec![argv.remove(0)];
        merged.extend(default_options.into_iter().map(std::ffi::OsString::from));
        merged.extend(argv);
        argv = merged;
    }
    let matches = cli::parse_args(argv);
    let parsed = args::parse(bin, &matches)?;
    let cli = match parsed {
        Parsed::LongHelp => {
            let mut cmd = cli::build_command()
                .bin_name(bin.to_string())
                .term_width(utils::terminal_width().unwrap_or(100));
            cmd.print_long_help()?;
            return Ok(0);
        }
        Parsed::Generate(kind) => {
            generation::generate(kind, bin)?;
            return Ok(0);
        }
        Parsed::Run(cli) => cli,
    };

    if cli.debug {
        env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("debug")).init();
        log::debug!("xh {} -native-tls +rustls", cli::VERSION);
        log::debug!("{:#?}", cli);
    }

    run_request(bin, *cli)
}

