/// Error carrying an explicit exit code.
#[derive(Debug)]
pub struct ExitCode(pub i32);

fn bin_name() -> String {
    std::env::args_os()
        .next()
        .map(|a| std::path::PathBuf::from(a))
        .and_then(|p| p.file_name().map(|f| f.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "xh".to_string())
}

fn main() {
    let bin = bin_name();
    let code = match run(&bin) {
        Ok(code) => code,
        Err(err) => {
            if let Some(exit) = err.downcast_ref::<args::ExitError>() {
                // clap style error: already formatted (usage included)
                let _ = std::io::stdout().flush();
                eprint!("{}", exit.message);
                if !exit.message.ends_with('\n') {
                    eprintln!();
                }
                exit.code
            } else if let Some(ExitCode(code)) = err.downcast_ref::<ExitCode>() {
                *code
            } else if err.downcast_ref::<QuietExit>().is_some() {
                err.downcast_ref::<QuietExit>().unwrap().0
            } else {
                let _ = std::io::stdout().flush();
                eprintln!("{}: error: {:?}", bin, err);
                let code = if is_timeout(&err) {
                    2
                } else if err.downcast_ref::<redirect::TooManyRedirects>().is_some() {
                    6
                } else {
                    1
                };
                code
            }
        }
    };
    std::process::exit(code);
}

/// Exit without printing anything more (message already printed).
#[derive(Debug)]
pub struct QuietExit(pub i32);

impl std::fmt::Display for QuietExit {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "exit {}", self.0)
    }
}

impl std::error::Error for QuietExit {}

impl std::fmt::Display for ExitCode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "exit code {}", self.0)
    }
}

impl std::error::Error for ExitCode {}

fn is_timeout(err: &anyhow::Error) -> bool {
    err.chain().any(|e| e.downcast_ref::<http::client::TimedOut>().is_some())
}

fn warn(bin: &str, quiet: u8, msg: &str) {
    if quiet < 2 {
        let _ = std::io::stdout().flush();
        eprintln!("{}: warning: {}", bin, msg);
    }
}

fn run(bin: &str) -> Result<i32> {
    let mut argv: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let default_options = config::default_options();
    if !default_options.is_empty() {
        let mut merged = vec![argv.remove(0)];
        merged.extend(default_options.into_iter().map(std::ffi::OsString::from));
        merged.extend(argv);
        argv = merged;
    }
    let matches = cli::parse_args(argv);
    let parsed = args::parse(bin, &matches)?;
    let cli = match parsed {
        Parsed::LongHelp => {
            let mut cmd = cli::build_command()
                .bin_name(bin.to_string())
                .term_width(utils::terminal_width().unwrap_or(100));
            cmd.print_long_help()?;
            return Ok(0);
        }
        Parsed::Generate(kind) => {
            generation::generate(kind, bin)?;
            return Ok(0);
        }
        Parsed::Run(cli) => cli,
    };

    if cli.debug {
        env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("debug")).init();
        log::debug!("xh {} -native-tls +rustls", cli::VERSION);
        log::debug!("{:#?}", cli);
    }

    run_request(bin, *cli)
}

fn read_stdin_body(cli: &Cli) -> Result<Option<Vec<u8>>> {
    if cli.ignore_stdin || std::io::stdin().is_terminal() {
        return Ok(None);
    }
    let mut buf = Vec::new();
    std::io::stdin().read_to_end(&mut buf)?;
    Ok(Some(buf))
}

/// The in-memory body with its content type and whether it can be printed.
struct BuiltBody {
    bytes: Vec<u8>,
    content_type: Option<String>,
    /// JSON-mode headers (Accept + Content-Type json) should be added
    json_headers: bool,
    /// Content-Length is shown when printing the request
    show_length: bool,
    /// Printable as text from memory
    printable: bool,
    present: bool,
}

fn run_request(bin: &str, mut cli: Cli) -> Result<i32> {
    let stdout_tty = utils::stdout_is_terminal();

    // ---- session ----------------------------------------------------------
    let mut session = match &cli.session {
        Some(name) => Some(session::Session::load(name, &cli.url, cli.is_session_read_only, bin)?),
        None => None,
    };

    // ---- stdin ------------------------------------------------------------
    let stdin_body = read_stdin_body(&cli)?;
    let body_type = cli.body_type();
    let has_data = cli.request_items.has_data();
    let file_body = cli.request_items.body_from_file.clone();

    if let Some(_) = &stdin_body {
        if cli.raw.is_some() {
            return Err(anyhow!(
                "Request body from stdin and --raw cannot be mixed. Pass --ignore-stdin to ignore standard input."
            ));
        }
        if has_data || file_body.is_some() {
            return Err(anyhow!(
                "Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input."
            ));
        }
        if body_type == BodyType::Multipart {
            return Err(anyhow!("Cannot build a multipart request body from stdin"));
        }
    }

    // ---- headers from items -----------------------------------------------
    let (user_headers, headers_to_unset) = cli.request_items.headers()?;

    // ---- body -------------------------------------------------------------
    let mut built = build_body(&cli, body_type, stdin_body.as_deref(), file_body.as_deref())?;

    // ---- method -----------------------------------------------------------
    let method = match &cli.method {
        Some(m) => m.clone(),
        None => {
            if built.present && !(body_type == BodyType::Form && !has_data && stdin_body.is_none() && cli.raw.is_none()) {
                "POST".to_string()
            } else {
                "GET".to_string()
            }
        }
    };

    // ---- compression ------------------------------------------------------
    let mut compressed = false;
    if cli.compress > 0 && built.present {
        if user_headers.contains_key("content-encoding") {
            warn(bin, cli.quiet, "--compress can't be used with a 'Content-Encoding:' header. --compress will be disabled.");
        } else if built.printable || !built.bytes.is_empty() {
            let mut encoder = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::default());
            encoder.write_all(&built.bytes)?;
            let data = encoder.finish()?;
            if cli.compress > 1 || data.len() < built.bytes.len() {
                built.bytes = data;
                compressed = true;
            }
        }
    }

    // ---- url (session / https) --------------------------------------------
    let mut url = cli.url.clone();
    let _ = url.set_fragment(url.fragment());

    // ---- build headers in order -------------------------------------------
    let version = match cli.http_version {
        Some(args::HttpVersion::Http10) => Version::Http10,
        Some(args::HttpVersion::Http2) | Some(args::HttpVersion::Http2PriorKnowledge) => Version::Http2,
        Some(args::HttpVersion::Http3PriorKnowledge) => {
            return Err(anyhow!("This binary was built without support for HTTP/3. Enable the `http3` feature."));
        }
        _ => Version::Http11,
    };

    let mut headers = HeaderMap::new();
    headers.insert(
        HeaderName::from_static("accept-encoding"),
        if cli.download { "identity" } else { DEFAULT_ACCEPT_ENCODING },
    );
    headers.insert(HeaderName::from_static("user-agent"), USER_AGENT);
    if version != Version::Http2 {
        headers.insert(HeaderName::from_static("connection"), "keep-alive");
    }
    if built.json_headers {
        headers.insert(HeaderName::from_static("accept"), "application/json, */*;q=0.5");
        headers.insert(HeaderName::from_static("content-type"), "application/json");
    } else if let Some(ct) = &built.content_type {
        headers.insert(HeaderName::from_static("content-type"), ct.as_str());
    }
    if compressed {
        headers.insert(HeaderName::from_static("content-encoding"), "deflate");
    }

    // ---- authentication ---------------------------------------------------
    let mut auth = auth::resolve_auth(&cli, &url, session.as_ref())?;
    // url credentials
    if !url.username().is_empty() || url.password().is_some() {
        let user = percent_encoding::percent_decode_str(url.username()).decode_utf8_lossy().into_owned();
        let pass = url.password().map(|p| percent_encoding::percent_decode_str(p).decode_utf8_lossy().into_owned());
        headers.insert(
            HeaderName::from_static("authorization"),
            auth::basic_auth_header(&user, pass.as_deref()),
        );
        let _ = url.set_username("");
        let _ = url.set_password(None);
    }
    let mut digest_auth: Option<(String, String)> = None;
    match &auth {
        Some(auth::Auth::Basic(user, pass)) => {
            headers.insert(
                HeaderName::from_static("authorization"),
                auth::basic_auth_header(user, pass.as_deref()),
            );
        }
        Some(auth::Auth::Bearer(token)) => {
            headers.insert(HeaderName::from_static("authorization"), format!("Bearer {}", token));
        }
        Some(auth::Auth::Digest(user, pass)) => {
            digest_auth = Some((user.clone(), pass.clone()));
        }
        None => {}
    }

    // session headers (before user headers)
    if let Some(s) = &session {
        for (name, value) in s.headers() {
            if let Ok(n) = HeaderName::new(&name) {
                headers.insert(n, value.into_bytes());
            }
        }
    }

    // user headers
    for (name, value) in user_headers.iter() {
        if headers.contains_key(name.as_str()) && !user_headers_seen(&headers, name, &user_headers) {
            headers.insert(name.clone(), value.to_vec());
        } else {
            headers.append(name.clone(), value.to_vec());
        }
    }
    // the loop above appends; fix: insert the first value of each name
    headers = merge_user_headers(headers, &user_headers);
    for name in &headers_to_unset {
        headers.remove(name.as_str());
    }

    // session update with headers/auth
    if let Some(s) = &mut session {
        s.save_headers(&user_headers, &headers_to_unset);
        if let Some(a) = &auth {
