            }
        } else if cli.output.is_some() || !stdout_tty {
            Pretty::None
        } else {
            default_pretty_for_terminal()
        }
    });
    let theme = cli.style.unwrap_or(Theme::Auto);
    let buffer = Buffer::new(cli.download, cli.output.as_deref(), stdout_tty)?;
    let print = match cli.print {
        Some(p) => p,
        None => Print::new(
            cli.verbose,
            cli.headers,
            cli.body,
            cli.meta,
            cli.quiet > 0,
            cli.offline,
            buffer.is_terminal(),
        ),
    };
    let history_print = cli.history_print.unwrap_or(print);
    let stream = cli.stream.unwrap_or(false);
    let mut printer = Printer::new(pretty, theme, stream, buffer, cli.format_options());
    printer.response_charset = cli.response_charset;
    printer.response_mime = cli.response_mime.clone();

    let request_body = if built.present {
        RequestBody::Bytes(built.bytes.clone())
    } else {
        RequestBody::Empty
    };
    let mut request = Request::new(&method, url.clone());
    request.headers = headers;
    request.body = request_body;
    request.version = version;

    // ---- curl -------------------------------------------------------------
    if cli.curl {
        let cmd = to_curl::translate(&cli, &request, &built, &user_headers, &headers_to_unset)?;
        println!("{}", cmd);
        return Ok(0);
    }

    // ---- offline ----------------------------------------------------------
    let print_headers = |request: &Request, printer: &mut Printer, jar: &cookies::CookieJar, show_length: bool| -> Result<()> {
        let mut display = request.headers.clone();
        finalize_headers(&mut display, request, jar, show_length, true);
        printer.print_request_headers(request, &display)?;
        Ok(())
    };

    if cli.offline {
        if print.request_headers {
            print_headers(&request, &mut printer, &cookie_jar, built.show_length)?;
        }
        if print.request_body && built.present {
            printer.print_request_body(&request.headers, &built.bytes, built.printable)?;
