    }

    // ---- send -------------------------------------------------------------
    let follow = cli.follow || cli.download;
    let max_redirects = cli.max_redirects.unwrap_or(10);
    let show_all = cli.all || cli.verbose > 0;
    let is_terminal_stdout = stdout_tty;

    let mut redirects = 0usize;
    let mut history_printed = false;
    let start = Instant::now();
    let final_response;
    let mut cur_request = request.clone();
    let mut cur_show_length = built.show_length;
    let mut cur_printable = built.printable;
    let mut elapsed;

    loop {
        // Add cookies for this request
        let mut send_request = cur_request.clone();
        finalize_headers(&mut send_request.headers, &cur_request, &cookie_jar, false, false);

        let this_print = if redirects == 0 { print } else { history_print };
        if this_print.request_headers {
            print_headers(&cur_request, &mut printer, &cookie_jar, cur_show_length)?;
        }
        if this_print.request_body && !cur_request.body.is_empty() {
            printer.print_request_body(&cur_request.headers, cur_request.body.as_bytes(), cur_printable)?;
        }
        printer.flush()?;

        if cur_request.version == Version::Http2 {
            // HTTP/2 over cleartext is not supported by this client.
            if cur_request.url.scheme() != "https" {
                if cli.http_version == Some(args::HttpVersion::Http2) {
                    warn(bin, cli.quiet, "Connection is HTTP/1, but request requires HTTP/2");
                    return Err(anyhow::Error::new(http::client::ChainError::chain(
                        &[&format!("error sending request for url ({})", cur_request.url)],
                        http::client::ChainError::new("client error (UserUnsupportedVersion)"),
                    )));
                }
                return Err(anyhow::Error::new(http::client::ChainError::chain(
                    &[&format!("error sending request for url ({})", cur_request.url), "client error (SendRequest)", "http2 error"],
                    http::client::ChainError::new("connection error detected: frame with invalid size"),
                )));
            }
            send_request.version = Version::Http11;
        }

        let req_start = Instant::now();
        let mut response = match client.send(&send_request) {
            Ok(r) => r,
            Err(e) => {
                return Err(anyhow::Error::new(http::client::ChainError::with_source(
                    format!("error sending request for url ({})", cur_request.url),
                    e,
                )));
            }
        };
        elapsed = req_start.elapsed();

        // digest auth challenge
        if response.status == 401 && digest_auth.is_some() && redirects == 0 && !send_request.headers.contains_key("authorization") {
            if let Some(challenge) = response.headers.get_str("www-authenticate") {
                if challenge.trim_start().to_ascii_lowercase().starts_with("digest") {
                    let (user, pass) = digest_auth.clone().unwrap();
                    let header = auth::digest_auth_header(&user, &pass, &cur_request.method, &cur_request.url, challenge)?;
                    // Print the intermediary exchange when --all/-v
                    if show_all {
                        if this_print.response_headers {
                            printer.print_response_headers(&response)?;
                        }
                        if this_print.response_body {
                            printer.print_response_body(&mut response)?;
                            printer.print_separator()?;
                        }
                        if this_print.response_meta {
                            printer.print_response_meta(elapsed, response.remote_addr)?;
                        }
                    } else {
                        let _ = response.read_body();
                    }
                    cookie_jar.store(&response.headers, &cur_request.url);
                    let mut next = cur_request.clone();
                    next.headers.insert(HeaderName::from_static("authorization"), header.into_bytes());
                    cur_request = next;
                    digest_auth = None;
                    redirects += 0;
                    history_printed = true;
                    continue;
                }
            }
        }

        cookie_jar.store(&response.headers, &cur_request.url);

        if follow && redirect::is_redirect(response.status) && response.headers.contains_key("location") {
            redirects += 1;
            if max_redirects != 0 && redirects >= max_redirects {
                // Print the last response like a final one before failing
                if show_all {
                    if history_print.response_headers {
                        printer.print_response_headers(&response)?;
                    }
                    if history_print.response_body {
                        printer.print_response_body(&mut response)?;
                        printer.print_separator()?;
                    }
                }
                printer.flush()?;
                return Err(anyhow::Error::new(redirect::TooManyRedirects(max_redirects)));
            }
            let next = match redirect::next_request(&cur_request, &response) {
                Some(n) => n,
                None => {
                    final_response = response;
                    break;
                }
            };
            if show_all {
                if history_print.response_headers {
                    printer.print_response_headers(&response)?;
                }
                if history_print.response_body {
                    printer.print_response_body(&mut response)?;
                    printer.print_separator()?;
                }
                if history_print.response_meta {
                    printer.print_response_meta(elapsed, response.remote_addr)?;
                }
            } else {
                let _ = response.read_body();
            }
            history_printed = true;
            if next.body.is_empty() {
                cur_show_length = false;
                cur_printable = true;
            }
            cur_request = next;
            continue;
        }
        final_response = response;
        break;
    }
    let _ = history_printed;
    let _ = start;

    let mut response = final_response;

    // ---- check status -----------------------------------------------------
    let check_status = cli.check_status.unwrap_or(!cli.httpie_compat_mode);
    let status = response.status;
    let mut exit_code = 0;
    if check_status {
        exit_code = match status {
            300..=399 if !follow => 3,
            400..=499 => 4,
            500..=599 => 5,
            _ => 0,
        };
        if exit_code != 0 && (printer.buffer.is_redirect() || cli.download || !is_terminal_stdout) && cli.quiet < 2 {
            let reason = if response.reason.is_empty() { String::new() } else { response.reason.clone() };
            warn(bin, cli.quiet, &format!("HTTP {} {}", status, reason));
        }
    }

    if print.response_headers {
        printer.print_response_headers(&response)?;
    }
    printer.flush()?;

    if cli.download {
        if exit_code == 0 || !check_status {
            download::download_file(&mut response, cli.output.clone(), cli.resume, &cli.url, cli.quiet > 0, bin)?;
        }
    } else if print.response_body {
        decompress_body(&mut response)?;
        printer.print_response_body(&mut response)?;
        if print.response_meta {
            printer.print_separator()?;
        }
    } else {
        let _ = response.read_body();
    }
    if print.response_meta {
        printer.print_response_meta(elapsed, response.remote_addr)?;
    }
    printer.flush()?;

    if let Some(s) = &mut session {
        s.save_cookies(&cookie_jar);
        s.persist()?;
    }

    Ok(exit_code)
}

fn user_headers_seen(_headers: &HeaderMap, _name: &HeaderName, _user: &HeaderMap) -> bool {
    false
}

/// Merge the user headers into the map: the first value of each header name
/// replaces an existing header in place, the following ones are appended.
fn merge_user_headers(base: HeaderMap, user: &HeaderMap) -> HeaderMap {
    // `base` already had user headers appended by the caller's loop; rebuild
    // cleanly from the non-user part to keep the semantics exact.
    let mut result = HeaderMap::new();
    let user_names: Vec<String> = user.names().map(|n| n.as_str().to_string()).collect();
    for (name, value) in base.iter() {
        if user_names.contains(&name.as_str().to_string()) {
            continue;
        }
        result.append(name.clone(), value.to_vec());
    }
    // Re-add base headers that are also user headers at their original
    // position by replacing in place.
    let mut rebuilt = HeaderMap::new();
    for name in base.names() {
        if user_names.contains(&name.as_str().to_string()) {
            // keep position with placeholder (first user value)
            if !rebuilt.contains_key(name.as_str()) {
                let values = user.get_all(name.as_str());
                if let Some(first) = values.first() {
                    rebuilt.insert(name.clone(), first.to_vec());
                }
            }
        } else {
            for v in base.get_all(name.as_str()) {
                rebuilt.append(name.clone(), v.to_vec());
            }
        }
    }
    for (name, value) in user.iter() {
        let existing = rebuilt.get_all(name.as_str());
        let already = existing.iter().any(|v| *v == value) && existing.len() == 1 && user.get_all(name.as_str()).len() == 1;
        if already {
            continue;
        }
        if !rebuilt.contains_key(name.as_str()) {
            rebuilt.insert(name.clone(), value.to_vec());
        } else if !existing.iter().any(|v| *v == value) || user.get_all(name.as_str()).len() > 1 {
            // append additional values (skip the first which was inserted)
            let first = user.get_all(name.as_str())[0];
            if value == first && existing.len() == 1 && existing[0] == first {
                continue;
            }
            rebuilt.append(name.clone(), value.to_vec());
        }
    }
    rebuilt
}

/// Add the headers that are computed at send/print time.
fn finalize_headers(headers: &mut HeaderMap, request: &Request, jar: &cookies::CookieJar, show_length: bool, for_display: bool) {
    if !headers.contains_key("accept") {
        headers.insert(HeaderName::from_static("accept"), "*/*");
    }
    if !for_display && !request.body.is_empty() {
        headers.insert(HeaderName::from_static("content-length"), request.body.len().to_string());
    }
    let cookie_header = jar.cookie_header(&request.url, headers.get("cookie"));
    if let Some(cookie) = cookie_header {
        headers.insert(HeaderName::from_static("cookie"), cookie.into_bytes());
    }
    if for_display && show_length && !request.body.is_empty() || for_display && show_length && request.body.is_empty() && show_length {
        headers.insert(HeaderName::from_static("content-length"), request.body.len().to_string());
    }
    if !headers.contains_key("host") {
        headers.insert(HeaderName::from_static("host"), request.host_header());
    }
}

fn default_pretty_for_terminal() -> Pretty {
    if std::env::var_os("TERM").map_or(false, |t| t == "dumb") {
        return Pretty::Format;
    }
    match std::env::var_os("NO_COLOR") {
        Some(v) if !v.is_empty() => Pretty::Format,
        _ => Pretty::All,
    }
}

fn proxy_config(cli: &Cli) -> http::client::ProxyConfig {
    let mut cfg = http::client::ProxyConfig { http: None, https: None, no_proxy: Vec::new() };
    if !cli.proxy.is_empty() {
        for p in &cli.proxy {
            match p {
                args::Proxy::Http(u) => cfg.http = Some(u.clone()),
                args::Proxy::Https(u) => cfg.https = Some(u.clone()),
                args::Proxy::All(u) => {
                    cfg.http = Some(u.clone());
                    cfg.https = Some(u.clone());
                }
            }
        }
        return cfg;
    }
    let env = |names: &[&str]| -> Option<::url::Url> {
        for n in names {
            if let Ok(v) = std::env::var(n) {
                if !v.is_empty() {
                    return ::url::Url::parse(&v).ok();
                }
            }
        }
        None
    };
    cfg.http = env(&["http_proxy", "HTTP_PROXY"]);
    cfg.https = env(&["https_proxy", "HTTPS_PROXY"]);
    if let Some(all) = env(&["all_proxy", "ALL_PROXY"]) {
        cfg.http.get_or_insert(all.clone());
        cfg.https.get_or_insert(all);
    }
    if let Ok(np) = std::env::var("NO_PROXY").or_else(|_| std::env::var("no_proxy")) {
        cfg.no_proxy = np.split(',').map(|s| s.trim().to_string()).collect();
    }
    cfg
}

fn build_body(cli: &Cli, body_type: BodyType, stdin: Option<&[u8]>, file: Option<&str>) -> Result<BuiltBody> {
    let mut built = BuiltBody {
        bytes: Vec::new(),
        content_type: None,
        json_headers: false,
        show_length: true,
        printable: true,
        present: false,
    };
    if let Some(raw) = &cli.raw {
        built.bytes = raw.as_bytes().to_vec();
        built.present = true;
        match body_type {
            BodyType::Json => built.json_headers = true,
            BodyType::Form => built.content_type = Some("application/x-www-form-urlencoded".to_string()),
            BodyType::Multipart => {}
        }
        return Ok(built);
    }
    if let Some(stdin) = stdin {
        built.bytes = stdin.to_vec();
        built.present = true;
        match body_type {
            BodyType::Json => built.json_headers = true,
            BodyType::Form => built.content_type = Some("application/x-www-form-urlencoded".to_string()),
            BodyType::Multipart => {}
        }
        return Ok(built);
    }
    if let Some(path) = file {
        if body_type != BodyType::Json {
            // form/multipart: file becomes a multipart part with an empty name
            let form = cli.request_items.body(BodyType::Multipart)?;
            if let Body::Multipart { text_fields, mut files } = form {
                files.push(request_items::FilePart { key: String::new(), path: path.to_string(), file_type: None, file_name: None });
                let (ct, bytes) = multipart::build(&text_fields, &files)?;
                built.bytes = bytes;
                built.content_type = Some(ct);
                built.present = true;
                built.show_length = false;
                return Ok(built);
            }
        }
        let bytes = std::fs::read(path).with_context(|| path.to_string())?;
        built.bytes = bytes;
        built.content_type = Some(request_items::file_body_content_type(path));
        built.present = true;
        built.show_length = false;
        return Ok(built);
    }
    let body = cli.request_items.body(body_type)?;
    match body {
        Body::Json(value) => {
            if let Some(value) = value {
                built.bytes = serde_json::to_vec(&value)?;
                built.present = true;
                built.json_headers = true;
            } else if cli.json {
                built.json_headers = true;
            }
        }
        Body::Form(fields) => {
            let mut ser = form_urlencoded::Serializer::new(String::new());
            for (k, v) in &fields {
                ser.append_pair(k, v);
            }
            built.bytes = ser.finish().into_bytes();
            built.content_type = Some("application/x-www-form-urlencoded".to_string());
            built.present = true;
        }
        Body::Multipart { text_fields, files } => {
            let (ct, bytes) = multipart::build(&text_fields, &files)?;
            built.bytes = bytes;
            built.content_type = Some(ct);
            built.present = true;
            built.show_length = false;
        }
        Body::File { .. } | Body::Raw(_) => unreachable!(),
    }
    Ok(built)
}

/// Wrap the response body reader in a decompressor if needed.
fn decompress_body(response: &mut http::Response) -> Result<()> {
    let encoding = response
        .headers
        .get_str("content-encoding")
        .map(|s| s.trim().to_ascii_lowercase())
        .unwrap_or_default();
    if encoding.is_empty() || encoding == "identity" {
        return Ok(());
    }
    let body = std::mem::replace(&mut response.body, Box::new(http::body::EmptyReader));
    let decoded: Box<dyn Read + Send> = match encoding.as_str() {
        "gzip" | "x-gzip" => Box::new(flate2::read::MultiGzDecoder::new(body)),
        "deflate" => Box::new(DeflateReader::new(body)),
        "br" => Box::new(crate::http::body::brotli_reader(body)?),
        _ => body,
    };
    response.body = decoded;
    Ok(())
}

/// Deflate reader that accepts both zlib-wrapped and raw deflate streams.
struct DeflateReader {
    inner: Option<Box<dyn Read + Send>>,
    decoder: Option<Box<dyn Read + Send>>,
    peeked: Vec<u8>,
}

impl DeflateReader {
    fn new(inner: Box<dyn Read + Send>) -> DeflateReader {
        DeflateReader { inner: Some(inner), decoder: None, peeked: Vec::new() }
    }
}

impl Read for DeflateReader {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        if self.decoder.is_none() {
            let mut inner = self.inner.take().unwrap();
            let mut head = [0u8; 2];
            let mut n = 0;
            while n < 2 {
                let r = inner.read(&mut head[n..])?;
                if r == 0 {
                    break;
                }
                n += r;
            }
            self.peeked = head[..n].to_vec();
            let is_zlib = n == 2 && (head[0] & 0x0f) == 8 && ((head[0] as u16) << 8 | head[1] as u16) % 31 == 0;
            let chained: Box<dyn Read + Send> = Box::new(std::io::Cursor::new(self.peeked.clone()).chain(inner));
            self.decoder = Some(if is_zlib {
                Box::new(flate2::read::ZlibDecoder::new(chained))
            } else {
                Box::new(flate2::read::DeflateDecoder::new(chained))
            });
        }
        self.decoder.as_mut().unwrap().read(buf)
    }
}
