//! Redirect handling.

use std::fmt;

use crate::headers::HeaderName;
use crate::http::{Request, RequestBody, Response};

#[derive(Debug)]
pub struct TooManyRedirects(pub usize);

impl fmt::Display for TooManyRedirects {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Too many redirects (--max-redirects={})", self.0)
    }
}

impl std::error::Error for TooManyRedirects {}

pub fn is_redirect(status: u16) -> bool {
    matches!(status, 301 | 302 | 303 | 307 | 308)
}

/// Build the request following the redirect, or None if the Location header
/// cannot be used.
pub fn next_request(request: &Request, response: &Response) -> Option<Request> {
    let location = response.headers.get_str("location")?;
    let url = request.url.join(location).ok()?;
    let mut next = request.clone();
    let cross_host = url.host_str() != request.url.host_str()
        || url.port_or_known_default() != request.url.port_or_known_default();

    match response.status {
        301 | 302 | 303 => {
            if request.method != "GET" && request.method != "HEAD" {
                next.method = "GET".to_string();
            }
            next.body = RequestBody::Empty;
            for name in ["transfer-encoding", "content-encoding", "content-type", "content-length"] {
                next.headers.remove(name);
            }
        }
        _ => {}
    }
    if cross_host {
        for name in ["authorization", "cookie", "cookie2", "proxy-authorization", "www-authenticate"] {
            next.headers.remove(name);
        }
    }
    let _ = HeaderName::from_static("location");
    next.url = url;
    Some(next)
}
