//! Authentication helpers (basic, bearer, digest, netrc).

use std::io::Write;

use anyhow::{anyhow, Result};
use base64::Engine;
use url::Url;

use crate::args::{AuthType, Cli};
use crate::session::Session;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Auth {
    Basic(String, Option<String>),
    Bearer(String),
    Digest(String, String),
}

pub fn basic_auth_header(user: &str, password: Option<&str>) -> String {
    let raw = format!("{}:{}", user, password.unwrap_or(""));
    format!("Basic {}", base64::engine::general_purpose::STANDARD.encode(raw))
}

/// Parse `USER[:PASS]`.
fn parse_user_pass(auth: &str) -> (String, Option<String>) {
    match auth.split_once(':') {
        Some((u, p)) => (u.to_string(), Some(p.to_string())),
        None => (auth.to_string(), None),
    }
}

fn prompt_password(user: &str, host: &str) -> Result<String> {
    use std::io::{BufRead, BufReader};
    let mut tty = std::fs::OpenOptions::new().read(true).write(true).open("/dev/tty")?;
    write!(tty, "http: password for {}@{}: ", user, host)?;
    tty.flush()?;
    // disable echo
    let fd = std::os::fd::AsRawFd::as_raw_fd(&tty);
    let mut termios: libc::termios = unsafe { std::mem::zeroed() };
    unsafe { libc::tcgetattr(fd, &mut termios) };
    let original = termios;
    termios.c_lflag &= !libc::ECHO;
    unsafe { libc::tcsetattr(fd, libc::TCSANOW, &termios) };
    let mut line = String::new();
    let result = BufReader::new(&tty).read_line(&mut line);
    unsafe { libc::tcsetattr(fd, libc::TCSANOW, &original) };
    writeln!(tty)?;
    result?;
    Ok(line.trim_end_matches(['\n', '\r']).to_string())
}

/// Work out which authentication to use for the request.
pub fn resolve_auth(cli: &Cli, url: &Url, session: Option<&Session>) -> Result<Option<Auth>> {
    let auth_type = cli.auth_type.unwrap_or(AuthType::Basic);
    let host = url.host_str().unwrap_or("");

    if let Some(token) = &cli.bearer {
        return Ok(Some(Auth::Bearer(token.clone())));
    }

    if let Some(auth) = &cli.auth {
        return Ok(Some(match auth_type {
            AuthType::Bearer => Auth::Bearer(auth.clone()),
            AuthType::Basic => {
                let (user, pass) = parse_user_pass(auth);
                let pass = match pass {
                    Some(p) => Some(p),
                    None => {
                        if crate::utils::stdin_is_terminal() || true {
                            Some(prompt_password(&user, host)?)
                        } else {
                            None
                        }
                    }
                };
                Auth::Basic(user, pass)
            }
            AuthType::Digest => {
                let (user, pass) = parse_user_pass(auth);
                let pass = match pass {
                    Some(p) => p,
                    None => prompt_password(&user, host)?,
                };
                Auth::Digest(user, pass)
            }
        }));
    }

    if let Some(session) = session {
        if let Some(auth) = session.auth() {
            return Ok(Some(auth));
        }
    }

    if !cli.ignore_netrc {
        if let Some(creds) = crate::netrc::lookup(host) {
            return Ok(Some(match auth_type {
                AuthType::Bearer => Auth::Bearer(creds.password),
                AuthType::Basic => Auth::Basic(creds.login, Some(creds.password)),
                AuthType::Digest => Auth::Digest(creds.login, creds.password),
            }));
        }
    }
    Ok(None)
}

