// Digest authentication
// ---------------------------------------------------------------------------

fn parse_challenge(challenge: &str) -> Vec<(String, String)> {
    let rest = challenge.trim_start();
    let rest = rest.strip_prefix("Digest").or_else(|| rest.strip_prefix("digest")).unwrap_or(rest);
    let mut params = Vec::new();
    let mut chars = rest.chars().peekable();
    loop {
        // skip separators
        while let Some(&c) = chars.peek() {
            if c == ',' || c.is_whitespace() {
                chars.next();
            } else {
                break;
            }
        }
        if chars.peek().is_none() {
            break;
        }
        let mut key = String::new();
        while let Some(&c) = chars.peek() {
            if c == '=' {
                break;
            }
            key.push(c);
            chars.next();
        }
        if chars.next().is_none() {
            break;
        }
        let mut value = String::new();
        if chars.peek() == Some(&'"') {
            chars.next();
            while let Some(c) = chars.next() {
                if c == '\\' {
                    if let Some(n) = chars.next() {
                        value.push(n);
                    }
                } else if c == '"' {
                    break;
                } else {
                    value.push(c);
                }
            }
        } else {
            while let Some(&c) = chars.peek() {
                if c == ',' {
                    break;
                }
                value.push(c);
                chars.next();
            }
        }
        params.push((key.trim().to_ascii_lowercase(), value.trim().to_string()));
    }
    params
}

pub fn digest_auth_header(user: &str, password: &str, method: &str, url: &Url, challenge: &str) -> Result<String> {
    let params = parse_challenge(challenge);
    let get = |k: &str| params.iter().find(|(key, _)| key == k).map(|(_, v)| v.clone());
    let realm = get("realm").unwrap_or_default();
    let nonce = get("nonce").ok_or_else(|| anyhow!("missing nonce in digest challenge"))?;
    let opaque = get("opaque");
    let algorithm = get("algorithm").unwrap_or_else(|| "MD5".to_string());
    let qop_options = get("qop").unwrap_or_default();
    let qop = if qop_options.split(',').any(|q| q.trim() == "auth") {
        Some("auth")
    } else if qop_options.split(',').any(|q| q.trim() == "auth-int") {
        Some("auth-int")
    } else {
        None
    };

    let mut uri = url.path().to_string();
    if let Some(q) = url.query() {
        uri.push('?');
        uri.push_str(q);
    }
    let cnonce = {
        use rand::RngCore;
        let mut bytes = [0u8; 16];
        rand::thread_rng().fill_bytes(&mut bytes);
        hex(&bytes)
    };
    let nc = "00000001";
    let is_sha256 = algorithm.to_ascii_uppercase().starts_with("SHA-256");
    let hash = |data: &str| -> String {
        if is_sha256 {
            sha256_hex(data.as_bytes())
        } else {
            md5_hex(data.as_bytes())
        }
    };
    let mut ha1 = hash(&format!("{}:{}:{}", user, realm, password));
    if algorithm.to_ascii_uppercase().ends_with("-SESS") {
        ha1 = hash(&format!("{}:{}:{}", ha1, nonce, cnonce));
    }
    let ha2 = if qop == Some("auth-int") {
        hash(&format!("{}:{}:{}", method, uri, hash("")))
    } else {
        hash(&format!("{}:{}", method, uri))
    };
    let response = match qop {
        Some(q) => hash(&format!("{}:{}:{}:{}:{}:{}", ha1, nonce, nc, cnonce, q, ha2)),
        None => hash(&format!("{}:{}:{}", ha1, nonce, ha2)),
    };

    let mut header = format!(
        "Digest username=\"{}\", realm=\"{}\", nonce=\"{}\", uri=\"{}\"",
        user, realm, nonce, uri
    );
    if let Some(q) = qop {
        header.push_str(&format!(", qop={}, nc={}, cnonce=\"{}\"", q, nc, cnonce));
    }
    header.push_str(&format!(", response=\"{}\"", response));
    if let Some(o) = opaque {
        header.push_str(&format!(", opaque=\"{}\"", o));
    }
    header.push_str(&format!(", algorithm={}", algorithm));
    Ok(header)
}

