    let mut month: Option<i64> = None;
    let mut year: Option<i64> = None;
    let mut time: Option<(i64, i64, i64)> = None;
    for t in &tokens {
        if t.contains(':') {
            let p: Vec<&str> = t.split(':').collect();
            if p.len() >= 2 {
                let h = p[0].parse().ok()?;
                let m = p[1].parse().ok()?;
                let sec = if p.len() > 2 { p[2].parse().unwrap_or(0) } else { 0 };
