            if day.is_none() && n <= 31 && t.len() <= 2 {
                day = Some(n);
            } else if year.is_none() {
                year = Some(if n < 70 { n + 2000 } else if n < 100 { n + 1900 } else { n });
            }
        }
    }
    let (day, month, year) = (day?, month?, year?);
    let (h, mi, sec) = time?;
    Some(days_from_civil(year, month, day) * 86400 + h * 3600 + mi * 60 + sec)
}

fn month_from(t: &str) -> Option<i64> {
    let t = t.to_ascii_lowercase();
    let months = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
    months.iter().position(|m| t.starts_with(m)).map(|i| i as i64 + 1)
}

