//! `--download` support.

use std::fs::{File, OpenOptions};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;

use anyhow::Result;
use url::Url;

use crate::http::Response;

/// Human readable size, like "1.95 KiB".
pub fn format_size(bytes: u64) -> String {
    const UNITS: [&str; 6] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
    if bytes < 1024 {
        return format!("{} B", bytes);
    }
    let mut value = bytes as f64;
    let mut unit = 0;
    while value >= 1024.0 && unit < UNITS.len() - 1 {
        value /= 1024.0;
        unit += 1;
    }
    format!("{:.2} {}", value, UNITS[unit])
}

fn format_speed(bytes: u64, secs: f64) -> String {
    let per_sec = if secs > 0.0 { bytes as f64 / secs } else { 0.0 };
    const UNITS: [&str; 6] = ["B/s", "KiB/s", "MiB/s", "GiB/s", "TiB/s", "PiB/s"];
    let mut value = per_sec;
    let mut unit = 0;
    while value >= 1024.0 && unit < UNITS.len() - 1 {
        value /= 1024.0;
        unit += 1;
    }
    if unit == 0 {
        format!("{} B/s", value as u64)
    } else {
        format!("{:.2} {}", value, UNITS[unit])
    }
}

/// File name from the Content-Disposition header.
fn filename_from_content_disposition(value: &str) -> Option<String> {
    for part in value.split(';') {
        let part = part.trim();
        if let Some(rest) = part.strip_prefix("filename*=") {
            // RFC 5987: charset'lang'value
            let mut it = rest.splitn(3, '\'');
            let _charset = it.next();
            let _lang = it.next();
            if let Some(v) = it.next() {
                let decoded = percent_encoding::percent_decode_str(v).decode_utf8_lossy().into_owned();
                if !decoded.is_empty() {
                    return Some(decoded);
                }
            }
        }
    }
    for part in value.split(';') {
        let part = part.trim();
        if let Some(rest) = part.strip_prefix("filename=") {
            let v = rest.trim().trim_matches('"');
            if !v.is_empty() {
                return Some(v.to_string());
            }
        }
    }
    None
}

fn extension_for_mime(ct: &str) -> Option<&'static str> {
    let essence = ct.split(';').next().unwrap_or("").trim();
    Some(match essence {
        "application/json" => "json",
        "text/plain" => "txt",
        "text/html" => "html",
        "text/css" => "css",
        "text/csv" => "csv",
        "text/xml" | "application/xml" => "xml",
        "application/javascript" | "text/javascript" => "js",
        "image/png" => "png",
        "image/jpeg" => "jpg",
        "image/gif" => "gif",
        "image/svg+xml" => "svg",
        "image/webp" => "webp",
        "application/pdf" => "pdf",
        "application/zip" => "zip",
        "application/gzip" => "gz",
        "application/octet-stream" => "bin",
        "text/markdown" => "md",
        "application/x-tar" => "tar",
        "application/wasm" => "wasm",
        "audio/mpeg" => "mp3",
        "video/mp4" => "mp4",
        "application/xhtml+xml" => "xhtml",
        _ => return None,
    })
}

fn sanitize(name: &str) -> String {
    let name: String = name.chars().filter(|c| *c != '/' && *c != '\0').collect();
    let name = name.trim_start_matches('.').to_string();
    if name.is_empty() {
        "index".to_string()
    } else {
        name
    }
}

/// Work out the file name for a download.
pub fn get_file_name(response: &Response, url: &Url) -> String {
    if let Some(cd) = response.headers.get_str("content-disposition") {
        if let Some(name) = filename_from_content_disposition(cd) {
            return sanitize(&name);
        }
    }
    let mut name = url
        .path_segments()
        .map(|segs| segs.filter(|s| !s.is_empty()).last().unwrap_or("").to_string())
        .unwrap_or_default();
    if name.is_empty() {
        name = "index".to_string();
    }
    let name = sanitize(&name);
    let has_extension = Path::new(&name).extension().is_some();
    if !has_extension {
        if let Some(ct) = response.headers.get_str("content-type") {
            if let Some(ext) = extension_for_mime(ct) {
                return format!("{}.{}", name, ext);
            }
        }
    }
    name
}

/// Find a name that does not exist yet (name, name-1, name-2, ...).
fn unique_name(name: &str) -> PathBuf {
    let base = Path::new(name);
    if !base.exists() {
        return base.to_path_buf();
    }
    let mut i = 1;
    loop {
        let candidate = PathBuf::from(format!("{}-{}", name, i));
        if !candidate.exists() {
            return candidate;
        }
        i += 1;
    }
}

pub fn download_file(
    response: &mut Response,
    output: Option<PathBuf>,
    resume: bool,
    url: &Url,
    quiet: bool,
    _bin: &str,
) -> Result<()> {
    let to_stdout = output.is_none() && !crate::utils::stdout_is_terminal();
    let content_length: Option<u64> = response
        .headers
        .get_str("content-length")
        .and_then(|v| v.trim().parse().ok());

    let (mut writer, display_name): (Box<dyn Write>, String) = if to_stdout {
        (Box::new(io::stdout()), "<stdout>".to_string())
    } else {
        let path = match &output {
            Some(p) => p.clone(),
            None => unique_name(&get_file_name(response, url)),
        };
        let file: File = if resume && response.status == 206 {
            OpenOptions::new().append(true).create(true).open(&path)?
        } else {
            File::create(&path)?
        };
        (Box::new(file), path.display().to_string())
    };

    let mut stderr = io::stderr();
    if !quiet {
        match content_length {
            Some(len) => writeln!(stderr, "Downloading {} to {:?}", format_size(len), display_name)?,
            None => writeln!(stderr, "Downloading to {:?}", display_name)?,
        }
    }

    let start = Instant::now();
    let mut buf = [0u8; 64 * 1024];
    let mut total: u64 = 0;
    loop {
        let n = response.body.read(&mut buf)?;
        if n == 0 {
            break;
        }
        writer.write_all(&buf[..n])?;
        total += n as u64;
    }
    writer.flush()?;
    let elapsed = start.elapsed().as_secs_f64();
    if !quiet {
        writeln!(
            stderr,
            "Done. {} in {:.5}s ({})",
            format_size(total),
            elapsed,
            format_speed(total, elapsed)
        )?;
    }
    Ok(())
}
EOF
echo ok"}

