pub fn translate(
    cli: &Cli,
    request: &Request,
    built: &BuiltBody,
    user_headers: &HeaderMap,
    headers_to_unset: &[HeaderName],
) -> Result<String> {
    let mut cmd = Cmd { long: cli.curl_long, args: Vec::new(), env: Vec::new(), warnings: Vec::new() };

