        if !timeout.0.is_zero() {
            cmd.args.push("--max-time".to_string());
            cmd.args.push(format_timeout(timeout.0));
        }
    }
    if let Some(v) = cli.http_version {
        cmd.args.push(
            match v {
                HttpVersion::Http10 => "--http1.0",
                HttpVersion::Http11 => "--http1.1",
                HttpVersion::Http2 => "--http2",
                HttpVersion::Http2PriorKnowledge => "--http2-prior-knowledge",
                HttpVersion::Http3PriorKnowledge => "--http3-only",
            }
            .to_string(),
        );
    }

