            Proxy::Http(url) => cmd.env.push(format!("http_proxy={}", shell_quote(url.as_str()))),
            Proxy::Https(url) => cmd.env.push(format!("https_proxy={}", shell_quote(url.as_str()))),
        }
    }
    if let Some(timeout) = &cli.timeout {
        if !timeout.0.is_zero() {
            cmd.args.push("--max-time".to_string());
            cmd.args.push(format_timeout(timeout.0));
        }
    }
    if let Some(v) = cli.http_version {
        cmd.args.push(
            match v {
                HttpVersion::Http10 => "--http1.0",
                HttpVersion::Http11 => "--http1.1",
                HttpVersion::Http2 => "--http2",
                HttpVersion::Http2PriorKnowledge => "--http2-prior-knowledge",
                HttpVersion::Http3PriorKnowledge => "--http3-only",
            }
            .to_string(),
        );
    }

    // method
    let method = request.method.as_str();
    let explicit_method = cli.method.is_some();
    let headers_only = cli.headers;
    if method == "OPTIONS" {
        cmd.flag("-i", "--include");
    }
    if method == "HEAD" {
        cmd.flag("-I", "--head");
    } else if headers_only {
        cmd.flag("-I", "--head");
        cmd.flag("-X", "--request");
        cmd.args.push(method.to_string());
        if built.present && method != "GET" {
            cmd.warn("-I/--head is incompatible with sending data. Consider omitting -h/--headers.");
        } else if explicit_method && method != "GET" {
            cmd.warn("-I/--head is incompatible with sending data. Consider omitting -h/--headers.");
        }
    } else if explicit_method {
        cmd.flag("-X", "--request");
        cmd.args.push(method.to_string());
    }
    if explicit_method && (cli.follow || cli.download) && !headers_only {
        cmd.warn("Using a combination of -X/--request and -L/--location which may cause unintended side effects.");
    }

    // URL
    let mut url = request.url.clone();
    if !cli.url.username().is_empty() || cli.url.password().is_some() {
        url = cli.url.clone();
    }
    cmd.args.push(shell_quote(url.as_str()));

    if cli.ipv4 && !cli.ipv6 {
        cmd.flag("-4", "--ipv4");
    } else if cli.ipv6 && !cli.ipv4 {
        cmd.flag("-6", "--ipv6");
    }
    if let Some(iface) = &cli.interface {
        cmd.args.push("--interface".to_string());
        cmd.args.push(shell_quote(iface));
    }
    if let Some(sock) = &cli.unix_socket {
        cmd.args.push("--unix-socket".to_string());
        cmd.args.push(shell_quote(&sock.to_string_lossy()));
    }
    if !cli.resolve.is_empty() {
        let port = url.port_or_known_default().unwrap_or(80);
        for r in &cli.resolve {
            cmd.args.push("--resolve".to_string());
            cmd.args.push(shell_quote(&format!("{}:{}:{}", r.domain, port, r.addr)));
        }
        cmd.warn("Inferred port number in --resolve from request URL.");
    }

    // headers
    for (name, value) in user_headers.iter() {
        let value = String::from_utf8_lossy(value);
        if value.is_empty() {
            cmd.header(&format!("{};", name.as_str()));
        } else {
            cmd.header(&format!("{}: {}", name.as_str(), value));
        }
    }
    for name in headers_to_unset {
        cmd.header(&format!("{}:", name.as_str()));
    }

    if cli.ignore_netrc {
        cmd.args.push("--no-netrc".to_string());
    }

    // auth
    let auth_type = cli.auth_type.unwrap_or(AuthType::Basic);
    if let Some(token) = &cli.bearer {
        cmd.args.push("--oauth2-bearer".to_string());
        cmd.args.push(shell_quote(token));
    } else if let Some(auth) = &cli.auth {
        match auth_type {
            AuthType::Bearer => {
                cmd.args.push("--oauth2-bearer".to_string());
                cmd.args.push(shell_quote(auth));
            }
            AuthType::Basic => {
                cmd.args.push("--basic".to_string());
                cmd.opt("-u", "--user", auth);
            }
            AuthType::Digest => {
                cmd.args.push("--digest".to_string());
                cmd.opt("-u", "--user", auth);
            }
        }
    }

    // body
    let body_type = cli.body_type();
    if let Some(raw) = &cli.raw {
        match body_type {
            BodyType::Json => {
                cmd.header("content-type: application/json");
                cmd.header("accept: application/json, */*;q=0.5");
            }
            BodyType::Form => cmd.header("content-type: application/x-www-form-urlencoded"),
            BodyType::Multipart => {}
        }
        cmd.opt("-d", "--data", raw);
    } else if let Some(path) = &cli.request_items.body_from_file {
        if body_type == BodyType::Json {
            cmd.header(&format!("content-type: {}", crate::request_items::file_body_content_type(path)));
            cmd.flag("--data-binary", "--data-binary");
            cmd.args.push(format!("@{}", path));
        } else {
            cmd.opt("-F", "--form", &format!("=@{}", path));
        }
    } else {
        match body_type {
            BodyType::Json => {
                let has_items = cli.request_items.has_data();
                if has_items || cli.json {
                    cmd.header("content-type: application/json");
                    cmd.header("accept: application/json, */*;q=0.5");
                }
                if has_items {
                    if let Body::Json(Some(value)) = cli.request_items.body(BodyType::Json)? {
                        cmd.opt("-d", "--data", &serde_json::to_string(&value)?);
                    }
                }
            }
            BodyType::Form if !cli.request_items.has_form_files() => {
                let body = cli.request_items.body(BodyType::Form)?;
                if let Body::Form(fields) = body {
                    if fields.is_empty() {
                        cmd.header("content-type: application/x-www-form-urlencoded");
                    }
                    for (k, v) in fields {
                        cmd.args.push("--data-urlencode".to_string());
                        cmd.args.push(shell_quote(&format!("{}={}", k, v)));
                    }
                }
            }
            BodyType::Form | BodyType::Multipart => {
                for item in &cli.request_items.items {
                    match item {
                        RequestItem::DataField { key, value } => {
                            cmd.opt("-F", "--form", &format!("{}={}", key, value));
                        }
                        RequestItem::FormFile { key, file_name, file_type, file_name_header } => {
                            let mut v = format!("{}=@{}", key, file_name);
                            if let Some(t) = file_type {
                                v.push_str(&format!(";type={}", t));
                            }
                            if let Some(n) = file_name_header {
                                v.push_str(&format!(";filename={}", n));
                            }
                            cmd.opt("-F", "--form", &v);
                        }
                        _ => {}
                    }
                }
            }
        }
    }

    // ignored options
    if cli.all || cli.verbose > 0 {
        cmd.warn("Ignored --all");
    }
    if cli.print.is_some() {
        cmd.warn("Ignored -p/--print");
    }
    if cli.body {
        cmd.warn("Ignored -b/--body");
    }
    if cli.pretty.is_some() {
        cmd.warn("Ignored --pretty");
    }
    if cli.style.is_some() {
        cmd.warn("Ignored -s/--style");
    }
    if cli.response_charset.is_some() {
        cmd.warn("Ignored --response-charset");
    }
    if cli.response_mime.is_some() {
        cmd.warn("Ignored --response-mime");
    }
    if cli.offline {
        cmd.warn("Ignored --offline");
    }
    if cli.session.is_some() {
        cmd.warn("Ignored --session");
    }
    if cli.native_tls {
        cmd.warn("Ignored --native-tls");
    }
    if cli.compress > 0 {
        cmd.warn("Ignored -x/--compress");
    }

    if !cmd.warnings.is_empty() {
        let mut err = std::io::stderr();
        use std::io::Write;
        for w in &cmd.warnings {
            let _ = writeln!(err, "Warning: {}", w);
        }
        let _ = writeln!(err);
    }

    let mut out = String::new();
    for e in &cmd.env {
        out.push_str(e);
        out.push(' ');
    }
    out.push_str("curl");
    for a in &cmd.args {
        out.push(' ');
        out.push_str(a);
    }
    Ok(out)
}

fn format_timeout(d: std::time::Duration) -> String {
    let secs = d.as_secs_f64();
    if secs.fract() == 0.0 {
        format!("{}", secs as u64)
    } else {
        format!("{}", secs)
    }
}
