//! `--generate`: shell completions and the man page.

use std::io::Write;

use anyhow::Result;
use clap::{Arg, Command};

use crate::args::Generate;
use crate::cli;

const MAN_TEMPLATE: &str = include_str!("../doc/man-template.roff");

pub fn generate(kind: Generate, bin_name: &str) -> Result<()> {
    let mut cmd = cli::build_command().bin_name(bin_name.to_string());
    let mut out = std::io::stdout();
    match kind {
        Generate::CompleteBash => clap_complete::generate(clap_complete::Shell::Bash, &mut cmd, bin_name, &mut out),
        Generate::CompleteElvish => clap_complete::generate(clap_complete::Shell::Elvish, &mut cmd, bin_name, &mut out),
        Generate::CompleteFish => clap_complete::generate(clap_complete::Shell::Fish, &mut cmd, bin_name, &mut out),
        Generate::CompletePowershell => {
            clap_complete::generate(clap_complete::Shell::PowerShell, &mut cmd, bin_name, &mut out)
        }
        Generate::CompleteZsh => clap_complete::generate(clap_complete::Shell::Zsh, &mut cmd, bin_name, &mut out),
        Generate::CompleteNushell => {
            cmd.build();
            let text = nushell(&cmd, bin_name);
            out.write_all(text.as_bytes())?;
        }
        Generate::Man => {
            cmd.build();
            let text = man_page(&cmd);
            out.write_all(text.as_bytes())?;
        }
    }
    out.flush()?;
    Ok(())
}

fn possible_values(arg: &Arg) -> Vec<String> {
    arg.get_possible_values()
        .iter()
        .filter(|v| !v.is_hide_set())
        .map(|v| v.get_name().to_string())
        .collect()
}

fn nushell(cmd: &Command, bin_name: &str) -> String {
    let mut s = String::new();
    s.push_str("module completions {\n\n");
    for arg in cmd.get_arguments() {
        let values = possible_values(arg);
        if !values.is_empty() && arg.get_action().takes_values() {
            s.push_str(&format!("  def \"nu-complete {} {}\" [] {{\n", bin_name, arg.get_id()));
            s.push_str("    [ ");
            for v in &values {
                s.push_str(&format!("\"{}\" ", v));
            }
            s.push_str("]\n  }\n\n");
        }
    }
    if let Some(about) = cmd.get_about() {
        s.push_str(&format!("  # {}\n", about));
    }
    s.push_str(&format!("  export extern {} [\n", bin_name));
    for arg in cmd.get_arguments() {
        let mut name = String::new();
        if arg.is_positional() {
            if arg.get_action().takes_values() && matches!(arg.get_num_args(), Some(n) if n.max_values() > 1) {
                name.push_str("...");
            }
            name.push_str(arg.get_id().as_str());
            name.push_str(": string");
        } else {
            name.push_str(&format!("--{}", arg.get_long().unwrap()));
            if let Some(short) = arg.get_short() {
                name.push_str(&format!("(-{})", short));
            }
            if arg.get_action().takes_values() {
                let values = possible_values(arg);
                if !values.is_empty() {
                    name.push_str(&format!(": string@\"nu-complete {} {}\"", bin_name, arg.get_id()));
                } else if matches!(arg.get_value_hint(), clap::ValueHint::FilePath | clap::ValueHint::AnyPath | clap::ValueHint::DirPath) {
                    name.push_str(": path");
                } else {
                    name.push_str(": string");
                }
            }
        }
        match arg.get_help() {
            Some(help) => s.push_str(&format!("    {:<25} # {}\n", name, help)),
            None => s.push_str(&format!("    {}\n", name)),
        }
    }
    s.push_str("  ]\n\n}\n\nexport use completions *\n");
    s
}

fn roff_escape(text: &str) -> String {
    text.replace('\\', "\\\\").replace('-', "\\-")
}

fn italic_value_name(name: &str) -> String {
    // Italicize runs of upper case letters, underscores and colons.
    let mut out = String::new();
    let mut run = String::new();
    let flush = |run: &mut String, out: &mut String| {
        if !run.is_empty() {
            out.push_str(&format!("\\fI{}\\fR", run));
            run.clear();
        }
    };
    for c in name.chars() {
        if c.is_ascii_uppercase() || c == '_' || c == ':' || c.is_ascii_digit() || c == '.' {
            run.push(c);
        } else {
            flush(&mut run, &mut out);
            out.push(c);
        }
    }
    flush(&mut run, &mut out);
    out
}

fn man_options(cmd: &Command) -> String {
    let mut s = String::new();
    for arg in cmd.get_arguments() {
        if arg.is_positional() || arg.is_hide_set() {
            continue;
        }
        s.push_str(".TP 4\n");
        let mut names = Vec::new();
        if let Some(short) = arg.get_short() {
            names.push(format!("\\fB\\-{}\\fR", short));
        }
        if let Some(long) = arg.get_long() {
            let mut n = format!("\\fB\\-\\-{}\\fR", roff_escape(long).trim_start_matches("\\-\\-"));
            if arg.get_action().takes_values() {
                let value_name = arg
                    .get_value_names()
                    .and_then(|v| v.first().map(|s| s.to_string()))
                    .unwrap_or_else(|| arg.get_id().to_string().to_uppercase());
                n.push('=');
                n.push_str(&italic_value_name(&value_name));
            }
            names.push(n);
        }
        s.push_str(&names.join(", "));
        s.push('\n');
        let help = arg
            .get_long_help()
            .or_else(|| arg.get_help())
            .map(|h| h.to_string())
            .unwrap_or_default();
        let mut help = roff_escape(&help);
        if !help.ends_with('.') {
            help.push('.');
        }
        s.push_str(&help);
        s.push('\n');
        let values = possible_values(arg);
        if !values.is_empty() && !arg.is_hide_possible_values_set() {
            s.push_str(&format!("\n[possible values: {}]\n", roff_escape(&values.join(", "))));
        }
    }
    s
}

const REQUEST_ITEMS_MAN: &str = r#"Optional key\-value pairs to be included in the request.

The separator is used to determine the type:
.RS 8
.TP 4
key==value
Add a query string to the URL.
.TP 4
key=value
Add a JSON property (\-\-json) or form field (\-\-form) to the request body.
.TP 4
key:=value
Add a field with a literal JSON value to the request body.

Example: "numbers:=[1,2,3] enabled:=true"
.TP 4
key@filename
Upload a file (requires \-\-form or \-\-multipart).

To set the filename and mimetype, ";type=" and ";filename=" can be used respectively.

Example: "pfp@ra.jpg;type=image/jpeg;filename=profile.jpg"
.TP 4
@filename
Use a file as the request body.
.TP 4
header:value
Add a header, e.g. "user\-agent:foobar"
.TP 4
header:
Unset a header, e.g. "connection:"
.TP 4
header;
Add a header with an empty value.
.RE

.RS
An "@" prefix can be used to read a value from a file. For example: "x\-api\-key:@api\-key.txt".

A backslash can be used to escape special characters, e.g. "weird\\:key=value".

To construct a complex JSON object, the REQUEST_ITEM's key can be set to a JSON path instead of a field name. For more information on this syntax, refer to https://httpie.io/docs/cli/nested\-json.
.RE"#;

fn today() -> String {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let days = secs.div_euclid(86400);
    // civil from days (Howard Hinnant's algorithm)
    let z = days + 719468;
    let era = z.div_euclid(146097);
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    format!("{:04}-{:02}-{:02}", y, m, d)
}

fn man_page(cmd: &Command) -> String {
    let mut options = man_options(cmd);
    // trailing newline handling: template has `{{options}}` followed by a newline
    if options.ends_with('\n') {
        options.pop();
    }
    MAN_TEMPLATE
        .replace("{{date}}", &today())
        .replace("{{version}}", cli::VERSION)
        .replace("{{request_items}}", REQUEST_ITEMS_MAN)
        .replace("{{options}}", &options)
}
