use std::ffi::{c_int, c_void, CString};
use std::io::{self, Read};
use std::sync::OnceLock;

type State = c_void;

#[allow(non_snake_case)]
struct Api {
    create: unsafe extern "C" fn(*const c_void, *const c_void, *mut c_void) -> *mut State,
    destroy: unsafe extern "C" fn(*mut State),
    decompress: unsafe extern "C" fn(*mut State, *mut usize, *mut *const u8, *mut usize, *mut *mut u8, *mut usize) -> c_int,
}

static API: OnceLock<Option<Api>> = OnceLock::new();

fn load() -> Option<Api> {
    unsafe {
        let mut handle = std::ptr::null_mut();
        for lib in ["libbrotlidec.so.1", "libbrotlidec.so"] {
            let c = CString::new(lib).unwrap();
            handle = libc::dlopen(c.as_ptr(), libc::RTLD_NOW);
            if !handle.is_null() {
                break;
            }
        }
        if handle.is_null() {
            return None;
        }
        let sym = |name: &str| -> *mut c_void {
            let c = CString::new(name).unwrap();
            libc::dlsym(handle, c.as_ptr())
        };
        let create = sym("BrotliDecoderCreateInstance");
        let destroy = sym("BrotliDecoderDestroyInstance");
        let decompress = sym("BrotliDecoderDecompressStream");
        if create.is_null() || destroy.is_null() || decompress.is_null() {
            return None;
        }
        Some(Api {
            create: std::mem::transmute(create),
            destroy: std::mem::transmute(destroy),
            decompress: std::mem::transmute(decompress),
        })
    }
}

const RESULT_ERROR: c_int = 0;
const RESULT_SUCCESS: c_int = 1;
const RESULT_NEEDS_MORE_INPUT: c_int = 2;

pub struct BrotliReader {
    api: &'static Api,
    state: *mut State,
    inner: Box<dyn Read + Send>,
    input: Vec<u8>,
    input_pos: usize,
    done: bool,
    eof: bool,
}

unsafe impl Send for BrotliReader {}

impl BrotliReader {
    pub fn new(inner: Box<dyn Read + Send>) -> io::Result<BrotliReader> {
        let api = API
            .get_or_init(load)
            .as_ref()
            .ok_or_else(|| io::Error::new(io::ErrorKind::Unsupported, "brotli decoding is unavailable"))?;
        let state = unsafe { (api.create)(std::ptr::null(), std::ptr::null(), std::ptr::null_mut()) };
        if state.is_null() {
            return Err(io::Error::new(io::ErrorKind::Other, "failed to create brotli decoder"));
        }
        Ok(BrotliReader { api, state, inner, input: vec![0; 16 * 1024], input_pos: 0, done: false, eof: false })
    }
}

impl Read for BrotliReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.done || buf.is_empty() {
            return Ok(0);
        }
        loop {
            if self.input_pos == 0 && !self.eof {
                let n = self.inner.read(&mut self.input)?;
                if n == 0 {
                    self.eof = true;
                }
                self.input_pos = n;
            }
            let mut available_in = self.input_pos;
            let mut next_in = self.input.as_ptr();
            let mut available_out = buf.len();
            let mut next_out = buf.as_mut_ptr();
            let rc = unsafe {
                (self.api.decompress)(
                    self.state,
                    &mut available_in,
                    &mut next_in,
                    &mut available_out,
                    &mut next_out,
                    std::ptr::null_mut(),
                )
            };
            // shift consumed input
            let consumed = self.input_pos - available_in;
            self.input.drain(..consumed);
            self.input.resize(16 * 1024, 0);
            self.input_pos = available_in;
            let produced = buf.len() - available_out;
            match rc {
                RESULT_ERROR => return Err(io::Error::new(io::ErrorKind::InvalidData, "brotli decoding error")),
                RESULT_SUCCESS => {
                    self.done = true;
                    return Ok(produced);
                }
                RESULT_NEEDS_MORE_INPUT => {
                    if produced > 0 {
                        return Ok(produced);
                    }
                    if self.eof {
                        return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "unexpected end of brotli stream"));
                    }
                    self.input_pos = 0;
                }
                _ => {
                    // needs more output
                    if produced > 0 {
                        return Ok(produced);
                    }
                }
            }
        }
    }
}

impl Drop for BrotliReader {
    fn drop(&mut self) {
        unsafe { (self.api.destroy)(self.state) };
    }
}
