/// Reader that yields EOF immediately when the underlying body is empty so
/// that decoders do not fail on empty bodies.
struct PeekReader {
    inner: Box<dyn Read + Send>,
    first: Option<Vec<u8>>,
    started: bool,
}

impl PeekReader {
    fn new(inner: Box<dyn Read + Send>) -> PeekReader {
        PeekReader { inner, first: None, started: false }
    }
}

impl Read for PeekReader {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        if !self.started {
            self.started = true;
            let mut tmp = vec![0u8; 8192];
            let n = self.inner.read(&mut tmp)?;
            tmp.truncate(n);
            self.first = Some(tmp);
        }
        if let Some(first) = &mut self.first {
            if first.is_empty() {
                self.first = None;
                return Ok(0);
            }
            let n = buf.len().min(first.len());
            buf[..n].copy_from_slice(&first[..n]);
            first.drain(..n);
            if first.is_empty() {
                self.first = None;
            }
            return Ok(n);
        }
        self.inner.read(buf)
    }
}

/// Maps decoder errors to the message format used for content decoding.
struct DecodeErrorReader {
    inner: Box<dyn Read + Send>,
    name: &'static str,
    empty: bool,
    started: bool,
}

impl DecodeErrorReader {
    fn new(inner: Box<dyn Read + Send>, name: &'static str) -> DecodeErrorReader {
        DecodeErrorReader { inner, name, empty: false, started: false }
    }
}

impl Read for DecodeErrorReader {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        if self.empty {
            return Ok(0);
        }
        match self.inner.read(buf) {
            Ok(n) => {
                self.started = true;
                Ok(n)
            }
            Err(e) => {
                if !self.started && e.kind() == std::io::ErrorKind::UnexpectedEof && self.name == "gzip" {
                    // empty body
                    self.empty = true;
                    return Ok(0);
                }
                let msg = match self.name {
                    "deflate" => "corrupt deflate stream".to_string(),
                    "brotli" => "Invalid Data".to_string(),
                    _ => e.to_string(),
                };
                Err(std::io::Error::new(
                    e.kind(),
                    http::client::ChainError::chain(
                        &[&format!("error decoding {} response body", self.name)],
                        http::client::ChainError::new(msg),
                    ),
                ))
            }
        }
    }
}

struct UnsupportedReader {
    body: Box<dyn Read + Send>,
    name: &'static str,
}

impl Read for UnsupportedReader {
    fn read(&mut self, _buf: &mut [u8]) -> std::io::Result<usize> {
        let mut sink = Vec::new();
        let _ = self.body.read_to_end(&mut sink);
        Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            format!("{} decoding is not supported by this build", self.name),
        ))
    }
}'''
