fn simplify_bash_file_completion(text: &str) -> String {
    let mut out = String::new();
    let lines: Vec<&str> = text.split('\\n').collect();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        if line.trim() == "local oldifs" {
            // find the compgen line within the block and skip the rest
            let mut j = i;
            let mut compgen = None;
            while j < lines.len() {
                let l = lines[j];
                if l.trim().starts_with("COMPREPLY=($(compgen -f") {
                    compgen = Some(l);
                }
                if l.trim() == "compopt -o filenames" {
                    // the closing `fi` follows
                    j += 1;
                    break;
                }
                j += 1;
            }
            if let Some(c) = compgen {
                out.push_str(c);
                out.push('\\n');
            }
            i = j + 1;
            continue;
        }
        out.push_str(line);
        if i + 1 < lines.len() {
            out.push('\\n');
        }
        i += 1;
    }
    out
}

