//! A minimal logger printing `[<elapsed>s LEVEL target] message` lines.

use std::io::Write;
use std::sync::OnceLock;
use std::time::Instant;

struct Logger {
    start: Instant,
    level: log::LevelFilter,
}

static LOGGER: OnceLock<Logger> = OnceLock::new();

impl log::Log for Logger {
    fn enabled(&self, metadata: &log::Metadata) -> bool {
        metadata.level() <= self.level
    }

    fn log(&self, record: &log::Record) {
        if !self.enabled(record.metadata()) {
            return;
        }
        let elapsed = self.start.elapsed().as_secs_f64();
        let mut stderr = std::io::stderr().lock();
        let _ = writeln!(
            stderr,
            "[{:.6}s {:<5} {}] {}",
            elapsed,
            record.level(),
            record.target(),
            record.args()
        );
    }

    fn flush(&self) {}
}

fn parse_level(spec: &str) -> log::LevelFilter {
    // Only the global level of a RUST_LOG spec is honoured.
    let first = spec.split(',').next().unwrap_or("").trim();
    let level = first.rsplit('=').next().unwrap_or(first);
    match level.to_ascii_lowercase().as_str() {
        "off" => log::LevelFilter::Off,
        "error" => log::LevelFilter::Error,
        "warn" => log::LevelFilter::Warn,
        "info" => log::LevelFilter::Info,
        "debug" => log::LevelFilter::Debug,
        "trace" => log::LevelFilter::Trace,
        _ => log::LevelFilter::Debug,
    }
}

/// Install the logger. `debug` forces at least debug level.
pub fn init(debug: bool) -> bool {
    let env = std::env::var("RUST_LOG").ok();
    let level = match (&env, debug) {
        (Some(spec), _) => parse_level(spec),
        (None, true) => log::LevelFilter::Debug,
        (None, false) => return false,
    };
    let logger = LOGGER.get_or_init(|| Logger { start: Instant::now(), level });
    if log::set_logger(logger).is_ok() {
        log::set_max_level(level);
        true
    } else {
        false
    }
}

pub fn active() -> bool {
    LOGGER.get().is_some()
}
