    width: usize,
}

impl ProgressBar {
    fn new(total: Option<u64>, start: Instant) -> ProgressBar {
        let width = crate::utils::terminal_width().unwrap_or(80);
        ProgressBar { total, start, last_draw: None, frame: 0, width }
    }

    fn render(&mut self, pos: u64) -> String {
