                };
                let suffix = format!("] {} {} ETA {}s", format_size(pos), speed, eta_secs.round() as u64);
                let visible = 2 + percent.to_string().len() + 3 + suffix.chars().count();
                let bar_width = self.width.saturating_sub(visible).max(1);
                let filled = if total == 0 { bar_width } else { (bar_width as u64 * pos / total.max(1)) as usize }.min(bar_width);
                let mut bar = String::new();
                bar.push_str("\\x1b[36m");
                if filled >= bar_width {
                    bar.push_str(&"#".repeat(bar_width));
                    bar.push_str("\\x1b[34m");
