                let visible = 2 + format_size(pos).len() + 1 + speed.len();
                let pad = self.width.saturating_sub(visible);
                format!("{}{}", text, " ".repeat(pad))
            }
        }
    }

    fn draw(&mut self, pos: u64, out: &mut dyn Write) -> io::Result<()> {
