            self.draw(pos, out)?;
        }
        Ok(())
    }

    fn finish(&mut self, pos: u64, out: &mut dyn Write) -> io::Result<()> {
        self.draw(pos, out)?;
        out.write_all(b"\\r\\x1b[2K")?;
        out.flush()
    }
}
